export const productI18n: Record<string, ProductI18n> = {
  "s2000-lamp": { intro: {"en": "The genuine 200 W high-pressure mercury short-arc lamp for the S2000 and S2000 Elite — a 250–600 nm continuous spectrum, up to 40 W/cm² in the long-wave UV, guaranteed for 2,000 hours and typically running to about 4,000. Standard and Surface Cure spectra, held in regional stock.", "zh": "S2000 与 S2000 Elite 的原厂 200 W 高压汞短弧灯——250–600 nm 连续光谱，长波紫外最高 40 W/cm²，保证寿命 2000 小时，实际使用通常可达约 4000 小时。提供标准型与表面固化型两种光谱，区域内备货。", "vi": "Đèn hồ quang ngắn thủy ngân cao áp 200 W chính hãng cho S2000 và S2000 Elite — phổ liên tục 250–600 nm, tới 40 W/cm² ở vùng UV sóng dài, bảo đảm 2.000 giờ và thực tế thường đạt khoảng 4.000 giờ. Có phổ Tiêu chuẩn và Surface Cure, sẵn kho trong khu vực.", "th": "หลอดอาร์กสั้นปรอทความดันสูง 200 วัตต์ ของแท้สำหรับ S2000 และ S2000 Elite — สเปกตรัมต่อเนื่อง 250–600 nm สูงถึง 40 W/cm² ในย่าน UV คลื่นยาว รับประกัน 2,000 ชั่วโมง และใช้งานจริงมักได้ราว 4,000 ชั่วโมง มีทั้งสเปกตรัมมาตรฐานและ Surface Cure พร้อมสต็อกในภูมิภาค"}, features: {"en": ["Genuine Excelitas lamp for the OmniCure S2000 and S2000 Elite", "200 W high-pressure mercury short-arc with a continuous 250–600 nm spectrum", "Up to 40 W/cm² in the long-wave UV", "Guaranteed 2,000 hours; approximately 4,000 hours typical in service", "Standard spectrum (S2000 Elite 012-68000R · S2000 012-64000R) covers the widest range of UV adhesive bonding", "Surface Cure spectrum (S2000 Elite 012-69000R · S2000 012-65000R) gives a smooth, tack-free finish on acrylic resins, overcoming oxygen inhibition", "Supplied as a bare spare lamp or as a complete Elite lamp module", "Held in regional stock, so a lamp change is a delivery rather than a lead time"], "zh": ["OmniCure S2000 与 S2000 Elite 的原厂灯", "200 W 高压汞短弧灯，250–600 nm 连续光谱", "长波紫外最高 40 W/cm²", "保证寿命 2000 小时，实际使用通常约 4000 小时", "标准型光谱（S2000 Elite 012-68000R · S2000 012-64000R）覆盖最广的 UV 胶粘接应用", "表面固化型光谱（S2000 Elite 012-69000R · S2000 012-65000R）克服氧阻聚，使丙烯酸树脂表面平滑不发粘", "可按裸灯管供货，也可整只 Elite 灯模块供货", "区域内备货，换灯是一次交付，而不是一段交期"], "vi": ["Đèn Excelitas chính hãng cho OmniCure S2000 và S2000 Elite", "Hồ quang ngắn thủy ngân cao áp 200 W, phổ liên tục 250–600 nm", "Tới 40 W/cm² ở vùng UV sóng dài", "Bảo đảm 2.000 giờ; thực tế thường khoảng 4.000 giờ", "Phổ Tiêu chuẩn (S2000 Elite 012-68000R · S2000 012-64000R) phủ dải ứng dụng dán keo UV rộng nhất", "Phổ Surface Cure (S2000 Elite 012-69000R · S2000 012-65000R) cho bề mặt nhựa acrylic nhẵn mịn, không dính tay, khắc phục ức chế oxy", "Cung cấp dạng đèn rời hoặc nguyên cụm mô-đun đèn Elite", "Sẵn kho trong khu vực, nên thay đèn là một lần giao hàng chứ không phải một kỳ chờ"], "th": ["หลอดของแท้จาก Excelitas สำหรับ OmniCure S2000 และ S2000 Elite", "หลอดอาร์กสั้นปรอทความดันสูง 200 วัตต์ สเปกตรัมต่อเนื่อง 250–600 nm", "สูงถึง 40 W/cm² ในย่าน UV คลื่นยาว", "รับประกัน 2,000 ชั่วโมง ใช้งานจริงมักราว 4,000 ชั่วโมง", "สเปกตรัมมาตรฐาน (S2000 Elite 012-68000R · S2000 012-64000R) ครอบคลุมงานยึดติดด้วยกาว UV ได้กว้างที่สุด", "สเปกตรัม Surface Cure (S2000 Elite 012-69000R · S2000 012-65000R) ให้ผิวเรซินอะคริลิกเรียบเนียน ไม่เหนียวติด แก้ปัญหาการยับยั้งจากออกซิเจน", "จัดส่งเป็นหลอดเปล่าหรือเป็นโมดูลหลอด Elite ทั้งชุด", "มีสต็อกในภูมิภาค การเปลี่ยนหลอดจึงเป็นการจัดส่ง ไม่ใช่ระยะเวลารอคอย"]} },
  "cv300-conveyor": { intro: {"en": "The conveyor built around the OmniCure AC Series of high-power UV LED heads — substrates to 310 mm wide on an open-mesh Teflon®-coated fibreglass belt, with the head height and angle adjustable to the part. Suits production, laboratory and R&D alike.", "zh": "围绕 OmniCure AC 系列大功率 UV LED 灯头打造的输送机——开孔网状特氟龙涂层玻纤皮带可承载宽至 310 mm 的基材，灯头高度与角度均可按工件调节。生产、实验室与研发场合皆适用。", "vi": "Băng tải được thiết kế quanh dòng đầu đèn UV LED công suất cao OmniCure AC Series — vật liệu nền rộng đến 310 mm trên băng sợi thủy tinh lưới hở phủ Teflon®, chiều cao và góc đầu đèn điều chỉnh theo chi tiết. Phù hợp cho sản xuất, phòng thí nghiệm và R&D.", "th": "สายพานลำเลียงที่ออกแบบมารอบหัวโคม UV LED กำลังสูงตระกูล OmniCure AC Series — รองรับวัสดุกว้างถึง 310 มม. บนสายพานไฟเบอร์กลาสตาข่ายเปิดเคลือบ Teflon® ปรับความสูงและมุมของหัวโคมตามชิ้นงานได้ เหมาะทั้งงานผลิต ห้องปฏิบัติการ และ R&D"}, features: {"en": ["Designed to complement the OmniCure AC Series of high-power UV LED curing systems", "Handles substrates up to 310 mm (12.2 in.) wide", "Effective curing area up to 300 mm (12 in.), depending on the LED system fitted", "Open-mesh Teflon®-coated fibreglass belt", "Belt speed adjustable from 1 to 14.5 m/min (3 to 48 ft/min)", "Head height adjustable from 30 to 60 mm in 10 mm increments", "Head angle adjustable 0 to 90° to the direction of belt travel, in 15° increments", "Suitable for production, laboratory and R&D use"], "zh": ["专为配合 OmniCure AC 系列大功率 UV LED 固化系统而设计", "可处理宽至 310 mm（12.2 英寸）的基材", "有效固化区域最大 300 mm（12 英寸），视所配 LED 系统而定", "开孔网状特氟龙涂层玻纤皮带", "皮带速度 1–14.5 m/min（3–48 ft/min）可调", "灯头高度 30–60 mm 可调，以 10 mm 为步进", "灯头角度相对皮带走向 0–90° 可调，以 15° 为步进", "适用于生产、实验室与研发场合"], "vi": ["Thiết kế để kết hợp với hệ UV LED công suất cao OmniCure AC Series", "Xử lý vật liệu nền rộng đến 310 mm (12,2 in.)", "Vùng đóng rắn hữu hiệu đến 300 mm (12 in.), tùy hệ LED lắp kèm", "Băng sợi thủy tinh lưới hở phủ Teflon®", "Tốc độ băng tải điều chỉnh 1 đến 14,5 m/phút (3 đến 48 ft/phút)", "Chiều cao đầu đèn điều chỉnh 30 đến 60 mm, bước 10 mm", "Góc đầu đèn điều chỉnh 0 đến 90° so với hướng chạy băng, bước 15°", "Phù hợp cho sản xuất, phòng thí nghiệm và R&D"], "th": ["ออกแบบมาเพื่อใช้ร่วมกับระบบ UV LED กำลังสูงตระกูล OmniCure AC Series", "รองรับวัสดุกว้างถึง 310 มม. (12.2 นิ้ว)", "พื้นที่บ่มใช้งานจริงถึง 300 มม. (12 นิ้ว) ขึ้นอยู่กับระบบ LED ที่ติดตั้ง", "สายพานไฟเบอร์กลาสตาข่ายเปิดเคลือบ Teflon®", "ปรับความเร็วสายพานได้ 1 ถึง 14.5 ม./นาที (3 ถึง 48 ฟุต/นาที)", "ปรับความสูงหัวโคมได้ 30 ถึง 60 มม. ทีละ 10 มม.", "ปรับมุมหัวโคมได้ 0 ถึง 90° เทียบกับทิศทางสายพาน ทีละ 15°", "เหมาะสำหรับงานผลิต ห้องปฏิบัติการ และ R&D"]} },
  "lc6-benchtop-conveyor": { intro: {"en": "The benchtop conveyor for laboratory and R&D evaluation — substrates to 190 mm wide with an effective UV width to 152 mm, paired with an F300S or LightHammer 6 Mark II lamp. Compact enough for a bench, rugged enough for small-part production.", "zh": "面向实验室与研发评估的台式输送机——可处理宽至 190 mm 的基材，有效紫外宽度达 152 mm，配 F300S 或 LightHammer 6 Mark II 灯系统。体积小到可放在台面上，结构坚固到能承接小件生产。", "vi": "Băng tải để bàn dành cho đánh giá trong phòng thí nghiệm và R&D — xử lý vật liệu nền rộng đến 190 mm với bề rộng UV hữu hiệu đến 152 mm, kết hợp với đèn F300S hoặc LightHammer 6 Mark II. Đủ nhỏ gọn cho mặt bàn, đủ bền cho sản xuất chi tiết nhỏ.", "th": "สายพานลำเลียงตั้งโต๊ะสำหรับการประเมินในห้องปฏิบัติการและงานวิจัยพัฒนา — รองรับวัสดุกว้างถึง 190 มม. ด้วยความกว้าง UV ใช้งานจริงถึง 152 มม. ใช้ร่วมกับหลอด F300S หรือ LightHammer 6 Mark II กะทัดรัดพอสำหรับวางบนโต๊ะ และแข็งแรงพอสำหรับผลิตชิ้นงานขนาดเล็ก"}, features: {"en": ["Handles substrates up to 190 mm (7.5 in.) wide; effective UV width up to 152 mm (6 in.)", "LC6B: lamp rotates 360° and adjusts vertically from focus at the belt to 76.2 mm beyond focus", "LC6B-2: vertical lamp adjustment only", "Air flows through the belt to cool the part and hold small sheets in place", "Teflon®-coated open-weave Kevlar® belt, carbon-impregnated and anti-static", "Four speed ranges from 0.6 to 76 m/min (2.0 to 250 fpm)", "Front-panel lamp control switch; zero-speed sensor protects lamp and belt", "Internal exhaust blower included; external blower optional"], "zh": ["可处理宽至 190 mm（7.5 英寸）的基材；有效紫外宽度达 152 mm（6 英寸）", "LC6B：灯头可 360° 旋转，并可从皮带面焦点垂直调节至焦点外 76.2 mm", "LC6B-2：仅支持垂直调节", "气流穿过皮带，既冷却工件，又将小片工件吸附定位", "特氟龙涂层疏织凯夫拉皮带，碳浸渍处理，具防静电性能", "四档速度范围，0.6–76 m/min（2.0–250 fpm）", "前面板灯控开关；零速传感器保护灯管与皮带", "标配内置排风机；可选外置排风机"], "vi": ["Xử lý vật liệu nền rộng đến 190 mm (7,5 in.); bề rộng UV hữu hiệu đến 152 mm (6 in.)", "LC6B: đèn xoay 360° và điều chỉnh dọc từ tiêu điểm tại mặt băng tải đến 76,2 mm ngoài tiêu điểm", "LC6B-2: chỉ điều chỉnh dọc", "Luồng khí qua băng tải làm mát chi tiết và giữ tấm nhỏ cố định", "Băng tải sợi Kevlar® dệt thưa phủ Teflon®, ngấm carbon, chống tĩnh điện", "Bốn dải tốc độ từ 0,6 đến 76 m/phút (2,0 đến 250 fpm)", "Công tắc điều khiển đèn trên mặt trước; cảm biến tốc độ bằng không bảo vệ đèn và băng tải", "Quạt hút khí trong máy đi kèm; quạt ngoài tùy chọn"], "th": ["รองรับวัสดุกว้างถึง 190 มม. (7.5 นิ้ว); ความกว้าง UV ใช้งานจริงถึง 152 มม. (6 นิ้ว)", "LC6B: หลอดหมุนได้ 360° และปรับแนวดิ่งจากจุดโฟกัสที่ผิวสายพานไปได้ถึง 76.2 มม. เลยจุดโฟกัส", "LC6B-2: ปรับได้เฉพาะแนวดิ่ง", "อากาศไหลผ่านสายพานเพื่อระบายความร้อนและยึดแผ่นงานขนาดเล็กให้อยู่กับที่", "สายพานเส้นใย Kevlar® ทอโปร่งเคลือบ Teflon® ผสมคาร์บอน ป้องกันไฟฟ้าสถิต", "สี่ช่วงความเร็ว ตั้งแต่ 0.6 ถึง 76 ม./นาที (2.0 ถึง 250 fpm)", "สวิตช์ควบคุมหลอดที่แผงหน้า; เซ็นเซอร์ความเร็วศูนย์ป้องกันหลอดและสายพาน", "มีพัดลมดูดอากาศภายในให้มาด้วย; พัดลมภายนอกเป็นตัวเลือก"]} },
  "drs-10-12-conveyor": { intro: {"en": "The floor-standing conveyor that takes one or two rows of Fusion UV modular curing systems — two 6-inch lamps side by side for a nominal 12-inch cure width, or 10-inch lamps in a two-row arrangement, over parts up to 4 inches high.", "zh": "可容纳一至两排 Fusion UV 模块化固化系统的落地式输送机——两支 6 英寸灯并排可获得标称 12 英寸固化宽度，或采用 10 英寸灯的双排布置，适用于高度 4 英寸以内的工件。", "vi": "Băng tải đặt sàn tiếp nhận một hoặc hai hàng hệ thống đóng rắn mô-đun Fusion UV — hai đèn 6 inch đặt cạnh nhau cho bề rộng đóng rắn danh nghĩa 12 inch, hoặc đèn 10 inch bố trí hai hàng, xử lý chi tiết cao đến 4 inch.", "th": "สายพานลำเลียงตั้งพื้นที่รองรับระบบบ่มแบบโมดูลของ Fusion UV หนึ่งหรือสองแถว — หลอด 6 นิ้วสองหลอดวางเคียงกันให้ความกว้างการบ่มระบุ 12 นิ้ว หรือหลอด 10 นิ้วจัดวางสองแถว สำหรับชิ้นงานสูงไม่เกิน 4 นิ้ว"}, features: {"en": ["Accepts one or two rows of Fusion UV modular microwave UV curing systems", "Two 6-inch lamps side by side for a nominal 12-inch curing width", "Two 10-inch lamps in a two-row arrangement", "Accommodates part geometries up to 4 inches high", "Lamp height, orientation, rows, cure width and belt speed all adjustable", "Digital speed indicator and safety interlocks", "Welded steel frame and lamp housing; built-in exhaust blower", "Base cabinet accommodates two power supplies"], "zh": ["可容纳一至两排 Fusion UV 模块化微波紫外固化系统", "两支 6 英寸灯并排，获得标称 12 英寸固化宽度", "两支 10 英寸灯采用双排布置", "可适应高度 4 英寸以内的各类工件形状", "灯高、朝向、排数、固化宽度与皮带速度均可调", "数字速度显示与安全联锁", "焊接钢制机架与灯罩；内置排风机", "底柜可容纳两台电源"], "vi": ["Tiếp nhận một hoặc hai hàng hệ thống UV vi sóng mô-đun Fusion UV", "Hai đèn 6 inch đặt cạnh nhau cho bề rộng đóng rắn danh nghĩa 12 inch", "Hai đèn 10 inch bố trí hai hàng", "Xử lý chi tiết có chiều cao đến 4 inch", "Điều chỉnh được chiều cao đèn, hướng đèn, số hàng, bề rộng đóng rắn và tốc độ băng tải", "Hiển thị tốc độ số và khóa liên động an toàn", "Khung thép hàn và vỏ đèn; quạt hút khí tích hợp", "Tủ đế chứa được hai bộ nguồn"], "th": ["รองรับระบบ UV ไมโครเวฟแบบโมดูลของ Fusion UV หนึ่งหรือสองแถว", "หลอด 6 นิ้วสองหลอดวางเคียงกัน ให้ความกว้างการบ่มระบุ 12 นิ้ว", "หลอด 10 นิ้วสองหลอดจัดวางสองแถว", "รองรับชิ้นงานรูปทรงต่าง ๆ สูงไม่เกิน 4 นิ้ว", "ปรับได้ทั้งความสูงหลอด ทิศทาง จำนวนแถว ความกว้างการบ่ม และความเร็วสายพาน", "จอแสดงความเร็วแบบดิจิทัลและระบบล็อกนิรภัย", "โครงเหล็กเชื่อมและตัวครอบหลอด; มีพัดลมดูดอากาศในตัว", "ตู้ฐานรองรับชุดจ่ายไฟได้สองชุด"]} },
  "drs-10-12-qn-conveyor": { intro: {"en": "The nitrogen-inerted version of the DRS floor-standing conveyor: an inerted cure zone with a chill bed reaching below 50 ppm oxygen, for chemistries that oxygen inhibits and for substrates that must not take the heat.", "zh": "DRS 落地式输送机的氮气惰化版本：惰化固化区配冷却台面，氧含量可低于 50 ppm，适用于受氧阻聚的化学体系，以及不能承受热负荷的基材。", "vi": "Phiên bản trơ hóa bằng nitơ của băng tải đặt sàn DRS: vùng đóng rắn trơ hóa kèm bàn làm mát, đạt dưới 50 ppm oxy, dành cho các hệ hóa học bị oxy ức chế và vật liệu nền không chịu được nhiệt.", "th": "รุ่นที่ใช้ไนโตรเจนไล่ออกซิเจนของสายพานตั้งพื้น DRS: โซนบ่มแบบไร้ออกซิเจนพร้อมแท่นทำความเย็น ลดออกซิเจนได้ต่ำกว่า 50 ppm สำหรับเคมีที่ถูกออกซิเจนยับยั้ง และวัสดุที่ทนความร้อนไม่ได้"}, features: {"en": ["Nitrogen-inerted cure zone with chill bed", "Below 50 ppm O₂ at 15 m/min (50 fpm) with a 6.4 mm snout opening", "Oxygen analyzer available", "Rotatable lamp boots", "Chill bed protects thermally sensitive substrates", "Same lamp flexibility as the DRS 10/12 — 6-inch and 10-inch systems, one or two rows"], "zh": ["氮气惰化固化区，配冷却台面", "在 15 m/min（50 fpm）、6.4 mm 出入口开度下，氧含量低于 50 ppm", "可配氧含量分析仪", "灯罩可旋转", "冷却台面保护热敏基材", "与 DRS 10/12 相同的灯配置灵活性——6 英寸与 10 英寸系统，一排或两排"], "vi": ["Vùng đóng rắn trơ hóa bằng nitơ kèm bàn làm mát", "Dưới 50 ppm O₂ ở 15 m/phút (50 fpm) với khe hở 6,4 mm", "Có sẵn máy phân tích oxy", "Chụp đèn xoay được", "Bàn làm mát bảo vệ vật liệu nền nhạy nhiệt", "Linh hoạt về đèn như DRS 10/12 — hệ 6 inch và 10 inch, một hoặc hai hàng"], "th": ["โซนบ่มแบบไล่ออกซิเจนด้วยไนโตรเจน พร้อมแท่นทำความเย็น", "ต่ำกว่า 50 ppm O₂ ที่ 15 ม./นาที (50 fpm) ด้วยช่องเปิด 6.4 มม.", "มีเครื่องวิเคราะห์ออกซิเจนให้เลือก", "ตัวครอบหลอดหมุนได้", "แท่นทำความเย็นปกป้องวัสดุที่ไวต่อความร้อน", "ความยืดหยุ่นด้านหลอดเท่ากับ DRS 10/12 — ระบบ 6 นิ้วและ 10 นิ้ว หนึ่งหรือสองแถว"]} },
  // ── Noblelight infrared heating modules (Excelitas IR brochure) ──
  "ir-m85": { intro: {"en": "The simplest module in the M series — an infrared emitter with its matched heat-reflector plate and holder, ready to fit where radiant heat is needed and nothing more complex is warranted.", "zh": "M 系列中结构最简明的模块——一支红外发射器，配以匹配的热反射板与支架，适用于只需辐射热、无需复杂配置的场合，出厂即可安装。", "vi": "Mô-đun đơn giản nhất trong dòng M — một bộ phát hồng ngoại cùng tấm phản xạ nhiệt và giá đỡ tương ứng, sẵn sàng lắp đặt ở nơi chỉ cần nhiệt bức xạ mà không đòi hỏi cấu hình phức tạp hơn.", "th": "โมดูลที่มีโครงสร้างเรียบง่ายที่สุดในซีรีส์ M — หลอดอินฟราเรดพร้อมแผ่นสะท้อนความร้อนและตัวยึดที่จับคู่กัน พร้อมติดตั้งในจุดที่ต้องการความร้อนแบบแผ่รังสีโดยไม่ต้องใช้โครงสร้างที่ซับซ้อนกว่านี้"}, features: {"en": ["Infrared emitter with an associated heat-reflector plate and holder", "Supplied assembled and ready for installation", "Several modules can be combined to build larger heating panels", "Retrofits easily into existing systems", "Cost-efficient, with a long service life"], "zh": ["红外发射器配匹配的热反射板与支架", "出厂完成装配，可直接安装", "多模块可组合成更大的加热面板", "可轻松改造接入现有系统", "成本效益高，使用寿命长"], "vi": ["Bộ phát hồng ngoại kèm tấm phản xạ nhiệt và giá đỡ tương ứng", "Cung cấp ở trạng thái đã lắp ráp, sẵn sàng lắp đặt", "Có thể ghép nhiều mô-đun thành tấm gia nhiệt lớn hơn", "Dễ dàng lắp bổ sung vào hệ thống hiện có", "Hiệu quả chi phí, tuổi thọ dài"], "th": ["หลอดอินฟราเรดพร้อมแผ่นสะท้อนความร้อนและตัวยึดที่จับคู่กัน", "จัดส่งในสภาพประกอบเสร็จ พร้อมติดตั้ง", "ประกอบหลายโมดูลเป็นแผงทำความร้อนขนาดใหญ่ได้", "ติดตั้งเพิ่มในระบบเดิมได้ง่าย", "คุ้มค่า พร้อมอายุการใช้งานยาวนาน"]} },
  "ir-m110": { intro: {"en": "One or more infrared emitters with the necessary ventilation, for installation where heat has to be applied rapidly and directly. Built from standard components, so it can be produced and supplied quickly.", "zh": "由一支或多支红外发射器与必要的通风系统构成，适用于需要快速、直接施加热量的场合。采用标准件构建，因而生产与供货周期短。", "vi": "Một hoặc nhiều bộ phát hồng ngoại kèm hệ thống thông gió cần thiết, dùng cho các vị trí cần cấp nhiệt nhanh và trực tiếp. Được chế tạo từ linh kiện tiêu chuẩn nên sản xuất và cung cấp nhanh chóng.", "th": "หลอดอินฟราเรดหนึ่งหลอดหรือมากกว่าพร้อมระบบระบายอากาศที่จำเป็น สำหรับติดตั้งในจุดที่ต้องให้ความร้อนอย่างรวดเร็วและโดยตรง ผลิตจากชิ้นส่วนมาตรฐานจึงผลิตและจัดส่งได้รวดเร็ว"}, features: {"en": ["One or more infrared emitters with the necessary ventilation", "For applications where heat must be applied rapidly and directly", "Built from standard components — quick to produce and supply", "Supplied assembled and ready for installation", "Several modules can be combined for larger heating panels"], "zh": ["一支或多支红外发射器，配必要的通风系统", "适用于需要快速、直接施加热量的场合", "采用标准件构建——生产与供货周期短", "出厂完成装配，可直接安装", "多模块可组合成更大的加热面板"], "vi": ["Một hoặc nhiều bộ phát hồng ngoại kèm hệ thống thông gió cần thiết", "Dành cho ứng dụng cần cấp nhiệt nhanh và trực tiếp", "Chế tạo từ linh kiện tiêu chuẩn — sản xuất và cung cấp nhanh", "Cung cấp ở trạng thái đã lắp ráp, sẵn sàng lắp đặt", "Có thể ghép nhiều mô-đun thành tấm gia nhiệt lớn hơn"], "th": ["หลอดอินฟราเรดหนึ่งหลอดหรือมากกว่า พร้อมระบบระบายอากาศที่จำเป็น", "สำหรับงานที่ต้องให้ความร้อนอย่างรวดเร็วและโดยตรง", "ผลิตจากชิ้นส่วนมาตรฐาน — ผลิตและจัดส่งได้รวดเร็ว", "จัดส่งในสภาพประกอบเสร็จ พร้อมติดตั้ง", "ประกอบหลายโมดูลเป็นแผงทำความร้อนขนาดใหญ่ได้"]} },
  "ir-m115": { intro: {"en": "One or two length-adjusted infrared emitters with ventilation, and the option to integrate pyrometers, temperature switches and temperature fuses — the M-series module for processes that need to be measured, not just heated.", "zh": "由一至两支按长度定制的红外发射器与通风系统构成，并可集成高温计、温度开关与温度熔断器——适用于不仅需要加热、更需要测量的工艺场合。", "vi": "Một hoặc hai bộ phát hồng ngoại được điều chỉnh theo chiều dài kèm hệ thống thông gió, có thể tích hợp hỏa kế, công tắc nhiệt và cầu chì nhiệt — mô-đun dòng M dành cho quy trình cần được đo lường chứ không chỉ gia nhiệt.", "th": "หลอดอินฟราเรดหนึ่งหรือสองหลอดที่ปรับความยาวตามการใช้งาน พร้อมระบบระบายอากาศ และสามารถติดตั้งไพโรมิเตอร์ สวิตช์อุณหภูมิ และฟิวส์อุณหภูมิเพิ่มเติมได้ — โมดูลซีรีส์ M สำหรับกระบวนการที่ต้องวัดผล ไม่ใช่เพียงให้ความร้อน"}, features: {"en": ["One or two length-adjusted infrared emitters", "Ventilation system included", "Pyrometers can be integrated for non-contact temperature measurement", "Temperature switches and temperature fuses can be integrated", "Supplied assembled and ready for installation"], "zh": ["一至两支按长度定制的红外发射器", "内置通风系统", "可集成高温计，实现非接触式测温", "可集成温度开关与温度熔断器", "出厂完成装配，可直接安装"], "vi": ["Một hoặc hai bộ phát hồng ngoại được điều chỉnh theo chiều dài", "Bao gồm hệ thống thông gió", "Có thể tích hợp hỏa kế để đo nhiệt độ không tiếp xúc", "Có thể tích hợp công tắc nhiệt và cầu chì nhiệt", "Cung cấp ở trạng thái đã lắp ráp, sẵn sàng lắp đặt"], "th": ["หลอดอินฟราเรดหนึ่งหรือสองหลอดที่ปรับความยาวตามการใช้งาน", "มีระบบระบายอากาศในตัว", "ติดตั้งไพโรมิเตอร์เพื่อวัดอุณหภูมิแบบไม่สัมผัสได้", "ติดตั้งสวิตช์อุณหภูมิและฟิวส์อุณหภูมิได้", "จัดส่งในสภาพประกอบเสร็จ พร้อมติดตั้ง"]} },
  "ir-mx-scalable": { intro: {"en": "A complete heating system rather than a single module: the MX carries an integrated control unit, and each module is optimised in size and wavelength to deliver energy effectively at the surface being heated.", "zh": "MX 不是单一模块，而是一套完整的加热系统：内置集成控制单元，每个模块的尺寸与波长均针对受热表面进行优化，以高效投放能量。", "vi": "Không chỉ là một mô-đun đơn lẻ mà là hệ thống gia nhiệt hoàn chỉnh: MX tích hợp sẵn bộ điều khiển, mỗi mô-đun được tối ưu về kích thước và bước sóng để truyền năng lượng hiệu quả lên bề mặt cần gia nhiệt.", "th": "ระบบทำความร้อนที่สมบูรณ์ ไม่ใช่เพียงโมดูลเดียว: MX มาพร้อมชุดควบคุมในตัว และแต่ละโมดูลได้รับการปรับขนาดและความยาวคลื่นให้เหมาะสม เพื่อส่งพลังงานไปยังพื้นผิวที่ต้องการให้ความร้อนอย่างมีประสิทธิภาพ"}, features: {"en": ["Integrated control unit — a system solution for the whole heating process", "Each module optimised in size and wavelength for the surface being heated", "Complete control systems available to regulate module power to line conditions", "Scales from an individual module to large heating fields, tunnels and ovens", "Applied across virtually all industrial sectors"], "zh": ["集成控制单元——面向整个加热工艺的系统方案", "每个模块的尺寸与波长针对受热表面优化", "可配套完整控制系统，按产线工况调节模块功率", "可从单个模块扩展至大型加热面、隧道炉与烘箱", "几乎适用于所有工业领域"], "vi": ["Bộ điều khiển tích hợp — giải pháp hệ thống cho toàn bộ quá trình gia nhiệt", "Mỗi mô-đun được tối ưu kích thước và bước sóng cho bề mặt cần gia nhiệt", "Có sẵn hệ điều khiển hoàn chỉnh để điều chỉnh công suất theo điều kiện dây chuyền", "Mở rộng từ một mô-đun đến trường gia nhiệt lớn, hầm và lò", "Ứng dụng trong hầu hết mọi lĩnh vực công nghiệp"], "th": ["ชุดควบคุมในตัว — โซลูชันระบบสำหรับกระบวนการทำความร้อนทั้งหมด", "แต่ละโมดูลปรับขนาดและความยาวคลื่นให้เหมาะกับพื้นผิวที่ให้ความร้อน", "มีระบบควบคุมครบชุดเพื่อปรับกำลังไฟตามสภาพสายการผลิต", "ขยายจากโมดูลเดียวไปสู่พื้นที่ทำความร้อนขนาดใหญ่ อุโมงค์ และเตาอบ", "ใช้งานได้แทบทุกภาคอุตสาหกรรม"]} },
  "ir-mx-advanced": { intro: {"en": "A tailor-made infrared system engineered to your process. Excelitas draws on a databank of over 3,000 infrared test reports and on application centres worldwide to determine the optimum heating solution before anything is built.", "zh": "面向您的工艺定制开发的红外系统。Excelitas 依托逾 3000 份红外测试报告的数据库与遍布全球的应用中心，在动工之前即确定最优加热方案。", "vi": "Hệ thống hồng ngoại được thiết kế riêng theo quy trình của bạn. Excelitas dựa trên kho dữ liệu hơn 3.000 báo cáo thử nghiệm hồng ngoại và các trung tâm ứng dụng trên toàn cầu để xác định giải pháp gia nhiệt tối ưu trước khi chế tạo.", "th": "ระบบอินฟราเรดที่ออกแบบเฉพาะสำหรับกระบวนการของคุณ Excelitas ใช้ฐานข้อมูลรายงานการทดสอบอินฟราเรดกว่า 3,000 ฉบับ ร่วมกับศูนย์ทดสอบการใช้งานทั่วโลก เพื่อกำหนดโซลูชันการให้ความร้อนที่เหมาะสมที่สุดก่อนเริ่มสร้างจริง"}, features: {"en": ["Tailor-made system solutions developed in close co-operation with you", "Databank of over 3,000 successful infrared test reports", "Application centres worldwide determine the optimum heating solution", "Emitters selected on output, voltage and wavelength for your requirement", "CAD data accepted in STEP, IGES, DWG and DXF formats", "CAE simulation instead of trial and error — shorter development, lower cost"], "zh": ["与您紧密协作开发的定制系统方案", "逾 3000 份成功红外测试报告的数据库", "全球应用中心确定最优加热方案", "按您的需求，从功率、电压与波长选定发射器", "接受 STEP、IGES、DWG、DXF 格式的 CAD 数据", "以 CAE 仿真取代试错——缩短开发周期、降低成本"], "vi": ["Giải pháp hệ thống thiết kế riêng, phát triển cùng bạn", "Kho dữ liệu hơn 3.000 báo cáo thử nghiệm hồng ngoại thành công", "Các trung tâm ứng dụng toàn cầu xác định giải pháp gia nhiệt tối ưu", "Chọn bộ phát theo công suất, điện áp và bước sóng phù hợp yêu cầu", "Nhận dữ liệu CAD định dạng STEP, IGES, DWG và DXF", "Mô phỏng CAE thay cho thử–sai — rút ngắn phát triển, giảm chi phí"], "th": ["โซลูชันระบบที่ออกแบบเฉพาะ พัฒนาร่วมกับคุณอย่างใกล้ชิด", "ฐานข้อมูลรายงานการทดสอบอินฟราเรดที่สำเร็จกว่า 3,000 ฉบับ", "ศูนย์ทดสอบการใช้งานทั่วโลกช่วยกำหนดโซลูชันที่เหมาะสมที่สุด", "เลือกหลอดตามกำลังไฟ แรงดัน และความยาวคลื่นตามความต้องการ", "รองรับข้อมูล CAD รูปแบบ STEP, IGES, DWG และ DXF", "ใช้การจำลอง CAE แทนการลองผิดลองถูก — พัฒนาเร็วขึ้น ต้นทุนต่ำลง"]} },
  "ir-control-systems": { intro: {"en": "A wide range of infrared control systems, from simple power controllers to complex, fully integrated PLC-based automation, designed to optimise the performance of your infrared emitters across all power ranges. Depending on the application, an optimised emitter can be combined with a custom IR module and adapted control system into a solution tailored to your heating process.", "zh": "覆盖面广泛的红外控制系统，从简易功率控制器到复杂的、完全集成的 PLC 自动化方案，用于在各功率区间优化红外发射器的运行表现。依据具体应用，可将优选的发射器与定制红外模块及适配的控制系统组合，形成贴合您加热工艺的整体方案。", "vi": "Dải sản phẩm hệ điều khiển hồng ngoại rộng, từ bộ điều khiển công suất đơn giản đến hệ tự động hóa phức hợp tích hợp hoàn toàn dựa trên PLC, được thiết kế để tối ưu hiệu năng của bộ phát hồng ngoại trên mọi dải công suất. Tùy theo ứng dụng, bộ phát được tối ưu có thể kết hợp với mô-đun hồng ngoại tùy chỉnh và hệ điều khiển thích ứng thành giải pháp phù hợp riêng cho quy trình gia nhiệt của bạn.", "th": "ระบบควบคุมอินฟราเรดหลากหลายรูปแบบ ตั้งแต่ตัวควบคุมกำลังไฟแบบเรียบง่ายไปจนถึงระบบอัตโนมัติที่ใช้ PLC แบบบูรณาการเต็มรูปแบบ ออกแบบมาเพื่อเพิ่มประสิทธิภาพการทำงานของหลอดอินฟราเรดในทุกช่วงกำลังไฟ ทั้งนี้ขึ้นอยู่กับการใช้งาน สามารถนำหลอดที่ผ่านการคัดเลือกมาผสานกับโมดูล IR ที่ออกแบบเฉพาะและระบบควบคุมที่ปรับให้เหมาะสม เพื่อสร้างโซลูชันที่ตรงกับกระบวนการให้ความร้อนของคุณ"}, features: {"en": ["Infinitely variable power output setting, with zero wear, low loss semi-conductor power boards", "Power-setting methods matched to your process", "Nominal value setting for infrared output by potentiometers, regulators or external signals", "Interface points with control can be classical contacts, analog signals or through modern fieldbus systems", "Robust housing with maximum protection and electrical safety, making it suitable for harsh industrial applications", "Contact breakers or fuses to protect emitter connections with small, easily manageable power cross-sections", "An emergency stop for isolating the load from the main supply", "Identification and reporting of failure of an emitter, a load fuse, a load board or a load voltage", "Control and monitoring of the infrared emitter module, including automatic control of module ventilation and temperature monitoring", "Industry-standard regulators, flexibly configurable, displaying nominal and actual values, timers, program indicators, ramp functions, limit function, PID self-optimization and manual/automatic tests"], "zh": ["功率输出无级可调，采用零磨损、低损耗半导体功率板", "功率设定方式与您的工艺相匹配", "红外输出的给定值可通过电位器、调节器或外部信号设定", "与控制系统的接口可采用传统触点、模拟信号或现代现场总线", "机壳坚固，具备高防护等级与电气安全性，适应严苛工业环境", "配备断路器或熔断器保护发射器接线，功率截面小、便于管理", "配备急停功能，可将负载与主电源隔离", "可识别并报告发射器、负载熔断器、功率板或负载电压的故障", "对红外发射器模块进行控制与监测，包括模块通风的自动控制与温度监控", "工业标准调节器，配置灵活，显示给定值与实际值，具备定时器、程序指示、斜坡功能、限值功能、PID 自整定及手动/自动测试"], "vi": ["Điều chỉnh công suất đầu ra vô cấp, với bo công suất bán dẫn không hao mòn, tổn hao thấp", "Phương thức đặt công suất phù hợp với quy trình của bạn", "Đặt giá trị danh định cho công suất hồng ngoại bằng chiết áp, bộ điều chỉnh hoặc tín hiệu bên ngoài", "Điểm giao tiếp với hệ điều khiển có thể là tiếp điểm truyền thống, tín hiệu analog hoặc fieldbus hiện đại", "Vỏ chắc chắn với mức bảo vệ và an toàn điện tối đa, phù hợp môi trường công nghiệp khắc nghiệt", "Cầu dao hoặc cầu chì bảo vệ đầu nối bộ phát với tiết diện công suất nhỏ, dễ quản lý", "Nút dừng khẩn cấp để cách ly tải khỏi nguồn điện chính", "Nhận diện và báo lỗi bộ phát, cầu chì tải, bo tải hoặc điện áp tải", "Điều khiển và giám sát mô-đun bộ phát hồng ngoại, gồm điều khiển thông gió tự động và giám sát nhiệt độ", "Bộ điều chỉnh theo chuẩn công nghiệp, cấu hình linh hoạt, hiển thị giá trị danh định và thực tế, hẹn giờ, chỉ báo chương trình, hàm dốc, hàm giới hạn, tự tối ưu PID và kiểm tra thủ công/tự động"], "th": ["ปรับตั้งกำลังไฟขาออกได้ต่อเนื่องไร้ขั้น ด้วยบอร์ดกำลังเซมิคอนดักเตอร์ที่ไม่สึกหรอและสูญเสียต่ำ", "วิธีตั้งค่ากำลังไฟที่เหมาะกับกระบวนการของคุณ", "ตั้งค่าเป้าหมายของกำลังอินฟราเรดด้วยโพเทนชิโอมิเตอร์ ตัวควบคุม หรือสัญญาณภายนอก", "จุดเชื่อมต่อกับระบบควบคุมเป็นได้ทั้งหน้าสัมผัสแบบดั้งเดิม สัญญาณแอนะล็อก หรือระบบฟิลด์บัสสมัยใหม่", "ตัวเครื่องแข็งแรง มีระดับการป้องกันและความปลอดภัยทางไฟฟ้าสูงสุด เหมาะกับงานอุตสาหกรรมที่สภาพแวดล้อมรุนแรง", "เบรกเกอร์หรือฟิวส์ป้องกันจุดต่อหลอด ด้วยขนาดพื้นที่หน้าตัดกำลังไฟที่เล็กและจัดการง่าย", "ปุ่มหยุดฉุกเฉินเพื่อตัดโหลดออกจากแหล่งจ่ายไฟหลัก", "ตรวจจับและรายงานความผิดปกติของหลอด ฟิวส์โหลด บอร์ดโหลด หรือแรงดันโหลด", "ควบคุมและเฝ้าติดตามโมดูลหลอดอินฟราเรด รวมถึงการควบคุมการระบายอากาศของโมดูลอัตโนมัติและการเฝ้าติดตามอุณหภูมิ", "ตัวควบคุมมาตรฐานอุตสาหกรรม ตั้งค่าได้ยืดหยุ่น แสดงค่าเป้าหมายและค่าจริง พร้อมตัวตั้งเวลา ตัวบ่งชี้โปรแกรม ฟังก์ชันแรมป์ ฟังก์ชันลิมิต PID ปรับค่าอัตโนมัติ และการทดสอบแบบแมนวล/อัตโนมัติ"]} },
  "ac2": { intro: {"en": "Compact AC275 and AC2110 air-cooled UV LED heads provide uniform small-area curing over 75 mm or 114 mm lengths, with up to 3 W/cm² at 365 nm and 4 W/cm² at 395 nm.", "zh": "AC2 系列包含结构紧凑的 AC275 与 AC2110 风冷 UV LED 灯头，分别覆盖 75 mm 与 114 mm 固化长度；365 nm 型号最高 3 W/cm²，395 nm 型号最高 4 W/cm²。", "vi": "Hệ thống đóng rắn UV LED làm mát bằng khí AC275 và AC2110 có thiết kế nhỏ gọn, lý tưởng cho các ứng dụng hạn chế không gian, sử dụng quang học mặt trước tiên tiến để đạt độ rọi đỉnh cao và độ đồng đều vượt trội. Phù hợp cho ứng dụng in ấn, thiết bị y tế, điện tử và quang điện tử.", "th": "หัวฉาย UV LED ระบายความร้อนด้วยอากาศ AC275 และ AC2110 ที่ออกแบบกะทัดรัด ให้การบ่มพื้นที่ขนาดเล็กอย่างสม่ำเสมอบนความยาว 75 mm หรือ 114 mm โดยให้กำลังสูงสุด 3 W/cm² ที่ 365 nm และ 4 W/cm² ที่ 395 nm"}, features: {"en": ["75 mm and 114 mm curing lengths", "365 nm and 395 nm wavelength options"], "zh": ["提供 75 mm 与 114 mm 两种固化长度", "支持 365 nm 与 395 nm 波长"], "vi": ["Kích thước nhỏ gọn, lý tưởng cho lắp đặt hạn chế không gian", "Quang học mặt trước tiên tiến cho độ rọi đỉnh cao và độ đồng đều"], "th": ["ความยาวการบ่ม 75 mm และ 114 mm","ตัวเลือกความยาวคลื่น 365 nm และ 395 nm"]} },
  "ac4": { intro: {"en": "AC450/P and AC475/P air-cooled UV LED heads deliver 8 W/cm² over 50 mm or 75 mm curing lengths at 365 nm or 395 nm. Print variants use application-specific optics.", "zh": "AC4 系列的 AC450/P 与 AC475/P 风冷 UV LED 灯头在 50 mm 或 75 mm 固化长度上提供 8 W/cm² 峰值辐照度，支持 365 nm 与 395 nm；P 型为印刷应用优化光学版本。", "vi": "Hệ thống đóng rắn UV LED diện tích nhỏ làm mát bằng khí AC450/P và AC475/P cung cấp độ rọi cao (8 W/cm²) ở khoảng cách làm việc linh hoạt, lý tưởng cho lắp ráp thiết bị y tế và ứng dụng điện tử cần đóng rắn năng suất cao, nhiệt độ thấp.", "th": "หัวฉาย UV LED ระบายความร้อนด้วยอากาศ AC450/P และ AC475/P ให้กำลัง 8 W/cm² บนความยาวการบ่ม 50 mm หรือ 75 mm ที่ 365 nm หรือ 395 nm รุ่นสำหรับงานพิมพ์ใช้ระบบออปติกที่ออกแบบเฉพาะการใช้งาน"}, features: {"en": ["8 W/cm² at 365 nm or 395 nm", "50 mm and 75 mm curing lengths"], "zh": ["365 nm 或 395 nm 下提供 8 W/cm²", "提供 50 mm 与 75 mm 两种固化长度"], "vi": ["Độ rọi cao 8 W/cm² ở khoảng cách làm việc linh hoạt", "Phù hợp đóng rắn năng suất cao, nhiệt độ thấp cho linh kiện nhựa"], "th": ["8 W/cm² ที่ 365 nm หรือ 395 nm","ความยาวการบ่ม 50 mm และ 75 mm"]} },
  "ac5": { intro: {"en": "AC550/P and AC575/P heads deliver 14 W/cm² at 395 nm; AC575-405 delivers 15 W/cm² at 405 nm. The compact, air-cooled heads require no external chiller or ozone extraction.", "zh": "AC5 系列的 AC550/P 与 AC575/P 在 395 nm 下提供 14 W/cm²，AC575-405 在 405 nm 下可达 15 W/cm²。灯头结构紧凑、采用风冷，无需外部冷水机或臭氧排放。", "vi": "Hệ thống UV LED làm mát bằng khí AC5 được thiết kế với sự kết hợp độc đáo giữa LED công suất cao và quang học tùy chỉnh, đạt tới 14 W/cm², cung cấp độ rọi cao ở khoảng cách làm việc linh hoạt. Thiết kế đầu nhỏ gọn loại bỏ nhu cầu làm mát ngoài hoặc hút khí ozone, đơn giản hóa tích hợp, và có thể lắp đặt theo mọi hướng.", "th": "หัวฉาย AC550/P และ AC575/P ให้กำลัง 14 W/cm² ที่ 395 nm ส่วน AC575-405 ให้ 15 W/cm² ที่ 405 nm หัวฉายกะทัดรัดระบายความร้อนด้วยอากาศ ไม่ต้องใช้เครื่องทำความเย็นภายนอกหรือระบบดูดโอโซน"}, features: {"en": ["14 W/cm² at 395 nm; 15 W/cm² with AC575-405", "No external chiller or ozone extraction"], "zh": ["395 nm 下为 14 W/cm²；AC575-405 可达 15 W/cm²", "无需外部冷水机或臭氧排放"], "vi": ["Độ rọi đỉnh lên đến 14-15 W/cm²", "Không cần làm mát ngoài hay hút ozone; lắp đặt theo mọi hướng"], "th": ["14 W/cm² ที่ 395 nm; 15 W/cm² ด้วย AC575-405","ไม่ต้องใช้เครื่องทำความเย็นภายนอกหรือระบบดูดโอโซน"]} },
  "ac7": { intro: {"en": "AC7150 and AC7300 air-cooled heads provide uniform 150 mm or 300 mm curing lengths, delivering 3 W/cm² at 365 nm or 5 W/cm² at 395 nm. Multiple heads can be adjoined.", "zh": "AC7 系列的 AC7150 与 AC7300 风冷灯头分别提供 150 mm 与 300 mm 固化长度；365 nm 下为 3 W/cm²，395 nm 下为 5 W/cm²，并支持多灯头拼接。", "vi": "AC7150 và AC7300 cung cấp độ đồng đều vượt trội trên toàn bộ vùng đóng rắn để đóng rắn đều và nhất quán. Nhiều hệ thống có thể ghép nối mà không ảnh hưởng độ đồng đều, mang lại tính linh hoạt cao hơn khi đóng rắn các bộ phận lớn hơn. Thiết kế cho lắp ráp thiết bị y tế, điện tử, ô tô, sợi quang và ứng dụng công nghiệp.", "th": "หัวฉายระบายความร้อนด้วยอากาศ AC7150 และ AC7300 ให้ความยาวการบ่มสม่ำเสมอ 150 mm หรือ 300 mm โดยให้กำลัง 3 W/cm² ที่ 365 nm หรือ 5 W/cm² ที่ 395 nm และสามารถต่อพ่วงหลายหัวเข้าด้วยกันได้"}, features: {"en": ["150 mm and 300 mm curing lengths", "3 W/cm² at 365 nm; 5 W/cm² at 395 nm"], "zh": ["提供 150 mm 与 300 mm 两种固化长度", "365 nm 下 3 W/cm²；395 nm 下 5 W/cm²"], "vi": ["Độ đồng đều vượt trội trên toàn vùng đóng rắn", "Có thể ghép nhiều hệ thống để mở rộng vùng đóng rắn mà không mất độ đồng đều"], "th": ["ความยาวการบ่ม 150 mm และ 300 mm","3 W/cm² ที่ 365 nm; 5 W/cm² ที่ 395 nm"]} },
  "ac8": { intro: {"en": "The AC8150/P, AC8225/P and AC8300/P air-cooled UV LED curing systems deliver over 8 W/cm2 peak irradiance for fast, even curing at long working distances. \"P\" versions feature enhanced optics optimized for short working distances required by print applications.", "zh": "AC8150/P、AC8225/P与AC8300/P风冷式UV LED固化系统峰值辐照度超过8 W/cm²，在长工作距离下实现快速均匀固化。\"P\"版本配备增强光学设计，专为印刷应用所需的短工作距离优化。", "vi": "Hệ thống đóng rắn UV LED làm mát bằng khí AC8150/P, AC8225/P và AC8300/P đạt độ rọi đỉnh trên 8 W/cm², đóng rắn nhanh và đều ở khoảng cách làm việc xa. Phiên bản \"P\" có quang học tăng cường tối ưu cho khoảng cách làm việc ngắn cần thiết trong ứng dụng in ấn.", "th": "ระบบบ่ม UV LED ระบายความร้อนด้วยอากาศ AC8150/P, AC8225/P และ AC8300/P ให้ความเข้มรังสีสูงสุดเกิน 8 W/cm2 เพื่อการบ่มที่รวดเร็วและสม่ำเสมอที่ระยะทำงานไกล รุ่น \"P\" มาพร้อมระบบออปติกที่ปรับปรุงให้เหมาะกับระยะทำงานสั้นที่งานพิมพ์ต้องการ"}, features: {"en": ["Over 8 W/cm2 peak irradiance for fast, even curing at long working distances", "\"P\" print versions optimized for short working distances"], "zh": ["峰值辐照度超过8 W/cm²，长工作距离下实现快速均匀固化", "\"P\"印刷版本针对短工作距离优化"], "vi": ["Độ rọi đỉnh trên 8 W/cm², đóng rắn nhanh đều ở khoảng cách xa", "Phiên bản in \"P\" tối ưu cho khoảng cách làm việc ngắn"], "th": ["ความเข้มรังสีสูงสุดเกิน 8 W/cm2 เพื่อการบ่มที่รวดเร็วและสม่ำเสมอที่ระยะทำงานไกล","รุ่นงานพิมพ์ \"P\" ปรับให้เหมาะกับระยะทำงานสั้น"]} },
  "ac8-hd": { intro: {"en": "The AC8-HD Series brings air-cooled UV LED curing to the next level, delivering over 15 W/cm2 peak irradiance and nearly double the dose of the AC8 Series, with innovative technology enabling unbeatable uniformity across the irradiation area. Offers three standard cure widths (6\", 9\", 12\") that can be adjoined for customized curing sizes.", "zh": "AC8-HD系列将风冷式UV LED固化技术推向新高度，峰值辐照度超过15 W/cm²，剂量几乎是AC8系列的两倍，并通过创新技术实现整个照射区域内无可匹敌的均匀性。提供三种标准固化宽度（6英寸、9英寸、12英寸），可拼接组合以定制固化尺寸。", "vi": "Dòng AC8-HD đưa công nghệ đóng rắn UV LED làm mát bằng khí lên một tầm cao mới, đạt độ rọi đỉnh trên 15 W/cm² và liều gần gấp đôi dòng AC8, với công nghệ đột phá mang lại độ đồng đều vượt trội trên toàn vùng chiếu xạ. Có ba độ rộng đóng rắn tiêu chuẩn (6\", 9\", 12\") có thể ghép nối để tùy chỉnh kích thước đóng rắn.", "th": "ซีรีส์ AC8-HD ยกระดับการบ่ม UV LED ระบายความร้อนด้วยอากาศไปอีกขั้น ด้วยความเข้มรังสีสูงสุดเกิน 15 W/cm2 และปริมาณรังสีเกือบสองเท่าของซีรีส์ AC8 พร้อมเทคโนโลยีล้ำสมัยที่มอบความสม่ำเสมอเหนือชั้นตลอดพื้นที่ฉายรังสี มีความกว้างการบ่มมาตรฐานสามขนาด (6\", 9\", 12\") ที่ต่อพ่วงกันได้เพื่อปรับขนาดการบ่มตามต้องการ"}, features: {"en": ["Over 15 W/cm2 peak irradiance, nearly double the dose of AC8 Series", "Three standard cure widths adjoinable for customized sizes"], "zh": ["峰值辐照度超过15 W/cm²，剂量近乎AC8系列的两倍", "三种标准固化宽度，可拼接定制尺寸"], "vi": ["Độ rọi đỉnh trên 15 W/cm², liều gần gấp đôi dòng AC8", "Ba độ rộng đóng rắn tiêu chuẩn, có thể ghép nối tùy chỉnh kích thước"], "th": ["ความเข้มรังสีสูงสุดเกิน 15 W/cm2 ปริมาณรังสีเกือบสองเท่าของซีรีส์ AC8","ความกว้างการบ่มมาตรฐานสามขนาด ต่อพ่วงกันได้เพื่อปรับขนาดตามต้องการ"]} },
  "ac9225": { intro: {"en": "The AC9 Series delivers 14 W/cm² in 150 mm, 225 mm and 300 mm air-cooled formats at 385 nm or 395 nm. Print variants at 395 nm are optimized for short working distances.", "zh": "AC9 系列在 150 mm、225 mm 与 300 mm 三种风冷规格中提供 14 W/cm²，支持 385 nm 与 395 nm；395 nm 的 P 型为短工作距离印刷应用优化。", "vi": "Dòng AC9 là hệ thống đóng rắn UV LED công suất cao, đạt độ rọi đỉnh trên 14 W/cm² để đóng rắn nhanh mực in, keo dán và sơn phủ. Thiết kế đột phá với giải pháp làm mát bằng khí hiệu suất cao, kích thước nhỏ gọn, cho phép tốc độ dây chuyền nhanh. Điều khiển từng mô-đun LED riêng lẻ mang lại độ đồng đều vượt trội, thiết kế mở rộng cho phép ghép nối nhiều đầu.", "th": "ซีรีส์ AC9 ให้กำลัง 14 W/cm² ในรูปแบบระบายความร้อนด้วยอากาศขนาด 150 mm, 225 mm และ 300 mm ที่ 385 nm หรือ 395 nm รุ่นสำหรับงานพิมพ์ที่ 395 nm ปรับให้เหมาะกับระยะทำงานสั้น"}, features: {"en": ["14 W/cm² peak irradiance", "150 mm, 225 mm and 300 mm lengths", "385 nm and 395 nm options"], "zh": ["峰值辐照度 14 W/cm²", "提供 150 mm、225 mm 与 300 mm 三种长度", "支持 385 nm 与 395 nm"], "vi": ["Độ rọi đỉnh trên 14 W/cm² để đóng rắn nhanh", "Điều khiển mô-đun LED riêng lẻ cho độ đồng đều đóng rắn vượt trội", "Thiết kế mở rộng — có thể ghép nối nhiều đầu"], "th": ["ความเข้มรังสีสูงสุด 14 W/cm²","ความยาว 150 mm, 225 mm และ 300 mm","ตัวเลือก 385 nm และ 395 nm"]} },
  "ac9225-f": { intro: {"en": "Specifically designed for fiber curing applications, the AC9225-F delivers up to 88 W/cm2 peak irradiance at the fiber in typical face-to-face configuration, with 10-18mm working distance. Reduces electrical power consumption by up to 60% compared to traditional arc lamp systems, with over 40,000 hours of LED lifetime and no replacement parts.", "zh": "AC9225-F专为光纤固化应用设计，在典型面对面配置下可实现高达88 W/cm²的峰值辐照度，工作距离为10-18毫米。相较传统电弧灯系统，可节省高达60%的电力消耗，LED寿命超过40,000小时，无需更换部件。", "vi": "Được thiết kế riêng cho ứng dụng đóng rắn sợi quang, AC9225-F đạt độ rọi đỉnh lên đến 88 W/cm² tại sợi quang trong cấu hình đối diện điển hình, khoảng cách làm việc 10-18mm. Giảm tiêu thụ điện lên đến 60% so với hệ thống đèn hồ quang truyền thống, tuổi thọ LED trên 40.000 giờ và không cần thay thế linh kiện.", "th": "ออกแบบมาเฉพาะสำหรับงานบ่มเส้นใยแก้วนำแสง AC9225-F ให้ความเข้มรังสีสูงสุดถึง 88 W/cm2 ที่เส้นใยในการจัดวางแบบหันหน้าเข้าหากันทั่วไป ด้วยระยะทำงาน 10-18mm ลดการใช้พลังงานไฟฟ้าได้ถึง 60% เมื่อเทียบกับระบบหลอดอาร์กแบบดั้งเดิม พร้อมอายุการใช้งาน LED เกิน 40,000 hours และไม่ต้องเปลี่ยนชิ้นส่วน"}, features: {"en": ["Up to 88 W/cm2 peak irradiance at the fiber", "Reduces power consumption by up to 60% vs. arc lamp systems", "Over 40,000 hours LED lifetime with no replacement parts"], "zh": ["光纤处峰值辐照度高达88 W/cm²", "相较电弧灯系统，节省高达60%电力消耗", "LED寿命超过40,000小时，无需更换部件"], "vi": ["Độ rọi đỉnh tại sợi quang lên đến 88 W/cm²", "Giảm tiêu thụ điện đến 60% so với hệ thống đèn hồ quang", "Tuổi thọ LED trên 40.000 giờ, không cần thay thế linh kiện"], "th": ["ความเข้มรังสีสูงสุดถึง 88 W/cm2 ที่เส้นใย","ลดการใช้พลังงานได้ถึง 60% เมื่อเทียบกับระบบหลอดอาร์ก","อายุการใช้งาน LED เกิน 40,000 hours โดยไม่ต้องเปลี่ยนชิ้นส่วน"]} },
  "f-series": { intro: {"en": "An economical electrodeless UV lamp system offering unlimited cure width by stacking lamps end-to-end. Features a semi-elliptical reflector geometry, optional dichroic reflectors, and optional mechanical shutter, suitable for a broad range of standard industrial UV curing applications.", "zh": "经济型无极UV灯系统，可通过首尾拼接灯具实现无限固化宽度。采用半椭圆反射器几何设计，可选配二向色反射器与机械快门，适用于各类标准工业UV Curing 紫外线固化应用。", "vi": "Hệ thống đèn UV không điện cực kinh tế, cho phép độ rộng đóng rắn không giới hạn bằng cách ghép nối các đèn nối tiếp. Có hình học gương phản xạ bán elip, gương phản xạ lưỡng sắc tùy chọn, và cửa chớp cơ học tùy chọn, phù hợp cho nhiều ứng dụng đóng rắn UV công nghiệp tiêu chuẩn.", "th": "ระบบหลอด UV แบบไร้ขั้วอิเล็กโทรดที่คุ้มค่า ให้ความกว้างการบ่มไม่จำกัดด้วยการต่อหลอดเรียงต่อกัน มาพร้อมรูปทรงตัวสะท้อนแบบครึ่งวงรี ตัวสะท้อนไดโครอิกเป็นตัวเลือก และชัตเตอร์เชิงกลเป็นตัวเลือก เหมาะสำหรับงาน UV Curing ในอุตสาหกรรมมาตรฐานหลากหลายประเภท"}, features: {"en": ["Unlimited cure width by stacking lamps end-to-end", "Fast startup: 20s cold start, 5s warm start (F300S/F300SQ)", "Standard external control and remote cooling blower"], "zh": ["灯具可首尾拼接，实现无限固化宽度", "启动迅速：冷启动20秒，热启动5秒（F300S/F300SQ）", "标配外部控制与远程冷却风机"], "vi": ["Độ rộng đóng rắn không giới hạn bằng ghép nối đèn nối tiếp", "Khởi động nhanh: khởi động nguội 20s, khởi động nóng 5s (F300S/F300SQ)", "Điều khiển ngoài tiêu chuẩn và quạt làm mát từ xa"], "th": ["ความกว้างการบ่มไม่จำกัดด้วยการต่อหลอดเรียงต่อกัน","เริ่มทำงานรวดเร็ว: สตาร์ตเย็น 20s สตาร์ตอุ่น 5s (F300S/F300SQ)","การควบคุมภายนอกมาตรฐานและพัดลมระบายความร้อนระยะไกล"]} },
  "fe100": { intro: {"en": "A natural convection-cooled UV LED system with WhisperCure technology, a thin form factor, and analog control, designed for pinning and gelling applications.", "zh": "采用自然对流冷却的UV LED系统，搭载WhisperCure技术，机身轻薄，支持模拟控制，专为点固化与凝胶化应用设计。", "vi": "Hệ thống UV LED làm mát bằng đối lưu tự nhiên với công nghệ WhisperCure, kích thước mỏng, và điều khiển tương tự, được thiết kế cho ứng dụng định hình và đông gel.", "th": "ระบบ UV LED ระบายความร้อนด้วยการพาความร้อนตามธรรมชาติ พร้อมเทคโนโลยี WhisperCure รูปทรงบาง และการควบคุมแบบแอนะล็อก ออกแบบมาสำหรับงานตรึงหมึก (pinning) และงานทำเจล"}, features: {"en": ["Natural convection cooling, no fan required", "Thin form factor designed for pinning and gelling"], "zh": ["自然对流冷却，无需风扇", "机身轻薄，专为点固化与凝胶化设计"], "vi": ["Làm mát đối lưu tự nhiên, không cần quạt", "Kích thước mỏng, thiết kế cho định hình và đông gel"], "th": ["ระบายความร้อนด้วยการพาความร้อนตามธรรมชาติ ไม่ต้องใช้พัดลม","รูปทรงบาง ออกแบบมาสำหรับงานตรึงหมึกและงานทำเจล"]} },
  "fe410": { intro: {"en": "An air-cooled UV LED system with TargetCure and WhisperCure technology delivering full cure, optics options, analog control, and a small form factor.", "zh": "风冷式UV LED系统，搭载TargetCure与WhisperCure技术，实现完全固化，提供光学选配方案，支持模拟控制，体积小巧。", "vi": "Hệ thống UV LED làm mát bằng khí với công nghệ TargetCure và WhisperCure mang lại đóng rắn hoàn toàn, tùy chọn quang học, điều khiển tương tự, và kích thước nhỏ gọn.", "th": "ระบบ UV LED ระบายความร้อนด้วยอากาศ พร้อมเทคโนโลยี TargetCure และ WhisperCure ที่ให้การบ่มเต็มรูปแบบ มีตัวเลือกออปติก การควบคุมแบบแอนะล็อก และรูปทรงกะทัดรัด"}, features: {"en": ["Full cure with TargetCure and WhisperCure technology", "Optics options available, small form factor"], "zh": ["搭载TargetCure与WhisperCure技术，实现完全固化", "提供光学选配方案，体积小巧"], "vi": ["Đóng rắn hoàn toàn với công nghệ TargetCure và WhisperCure", "Có tùy chọn quang học, kích thước nhỏ gọn"], "th": ["บ่มเต็มรูปแบบด้วยเทคโนโลยี TargetCure และ WhisperCure","มีตัวเลือกออปติก รูปทรงกะทัดรัด"]} },
  "firejet-one": { intro: {"en": "An air-cooled UV LED system with TargetCure and WhisperCure technology, offering high irradiance in a small, scalable form factor with optional Ethernet communication.", "zh": "风冷式UV LED系统，搭载TargetCure与WhisperCure技术，体积小巧、可扩展，提供高辐照度，并支持可选以太网通信。", "vi": "Hệ thống UV LED làm mát bằng khí với công nghệ TargetCure và WhisperCure, mang lại độ rọi cao trong kích thước nhỏ gọn, có thể mở rộng, với giao tiếp Ethernet tùy chọn.", "th": "ระบบ UV LED ระบายความร้อนด้วยอากาศ พร้อมเทคโนโลยี TargetCure และ WhisperCure ให้ความเข้มรังสีสูงในรูปทรงกะทัดรัดที่ขยายขนาดได้ พร้อมการสื่อสาร Ethernet เป็นตัวเลือก"}, features: {"en": ["TargetCure and WhisperCure technology", "High irradiance in a small, scalable form factor"], "zh": ["搭载TargetCure与WhisperCure技术", "体积小巧可扩展，辐照度高"], "vi": ["Công nghệ TargetCure và WhisperCure", "Độ rọi cao trong kích thước nhỏ gọn, có thể mở rộng"], "th": ["เทคโนโลยี TargetCure และ WhisperCure","ความเข้มรังสีสูงในรูปทรงกะทัดรัดที่ขยายขนาดได้"]} },
  "fj100": { intro: {"en": "An air-cooled, scalable UV LED system with TargetCure and WhisperCure technology, digital/analog control, and optional Ethernet communication for high irradiance curing applications.", "zh": "风冷式、可扩展的UV LED系统，搭载TargetCure与WhisperCure技术，支持数字/模拟控制及可选以太网通信，适用于高辐照度固化应用。", "vi": "Hệ thống UV LED làm mát bằng khí, có thể mở rộng với công nghệ TargetCure và WhisperCure, điều khiển số/tương tự, và giao tiếp Ethernet tùy chọn cho ứng dụng đóng rắn độ rọi cao.", "th": "ระบบ UV LED ระบายความร้อนด้วยอากาศที่ขยายขนาดได้ พร้อมเทคโนโลยี TargetCure และ WhisperCure การควบคุมแบบดิจิทัล/แอนะล็อก และการสื่อสาร Ethernet เป็นตัวเลือก สำหรับงานบ่มที่ต้องการความเข้มรังสีสูง"}, features: {"en": ["TargetCure and WhisperCure technology", "Digital/analog control with optional Ethernet communication"], "zh": ["搭载TargetCure与WhisperCure技术", "支持数字/模拟控制及可选以太网通信"], "vi": ["Công nghệ TargetCure và WhisperCure", "Điều khiển số/tương tự với giao tiếp Ethernet tùy chọn"], "th": ["เทคโนโลยี TargetCure และ WhisperCure","การควบคุมแบบดิจิทัล/แอนะล็อก พร้อมการสื่อสาร Ethernet เป็นตัวเลือก"]} },
  "fj240": { intro: {"en": "An air-cooled, scalable UV LED system featuring TargetCure technology and high dose output, with digital/analog control and optional Ethernet communication.", "zh": "风冷式、可扩展的UV LED系统，搭载TargetCure技术，提供高剂量输出，支持数字/模拟控制及可选以太网通信。", "vi": "Hệ thống UV LED làm mát bằng khí, có thể mở rộng với công nghệ TargetCure và đầu ra liều cao, điều khiển số/tương tự và giao tiếp Ethernet tùy chọn.", "th": "ระบบ UV LED ระบายความร้อนด้วยอากาศที่ขยายขนาดได้ มาพร้อมเทคโนโลยี TargetCure และเอาต์พุตปริมาณรังสีสูง พร้อมการควบคุมแบบดิจิทัล/แอนะล็อก และการสื่อสาร Ethernet เป็นตัวเลือก"}, features: {"en": ["High dose output with TargetCure technology", "Scalable design with digital/analog control"], "zh": ["搭载TargetCure技术，提供高剂量输出", "可扩展设计，支持数字/模拟控制"], "vi": ["Đầu ra liều cao với công nghệ TargetCure", "Thiết kế mở rộng với điều khiển số/tương tự"], "th": ["เอาต์พุตปริมาณรังสีสูงด้วยเทคโนโลยี TargetCure","ดีไซน์ที่ขยายขนาดได้ พร้อมการควบคุมแบบดิจิทัล/แอนะล็อก"]} },
  "fj801": { intro: {"en": "An air-cooled UV LED area curing system featuring TargetCure technology, exceptional uniformity, and a separate controller, designed for area curing applications.", "zh": "风冷式UV LED面固化系统，搭载TargetCure技术，均匀性卓越，配备独立控制器，专为面固化应用设计。", "vi": "Hệ thống đóng rắn diện tích UV LED làm mát bằng khí với công nghệ TargetCure, độ đồng đều vượt trội, và bộ điều khiển riêng, được thiết kế cho ứng dụng đóng rắn diện tích.", "th": "ระบบบ่มพื้นที่ UV LED ระบายความร้อนด้วยอากาศ มาพร้อมเทคโนโลยี TargetCure ความสม่ำเสมอยอดเยี่ยม และตัวควบคุมแยกต่างหาก ออกแบบมาสำหรับงานบ่มพื้นที่"}, features: {"en": ["Exceptional uniformity for area curing applications", "Separate controller, scalable design"], "zh": ["面固化应用中均匀性卓越", "配备独立控制器，可扩展设计"], "vi": ["Độ đồng đều vượt trội cho ứng dụng đóng rắn diện tích", "Bộ điều khiển riêng, thiết kế mở rộng"], "th": ["ความสม่ำเสมอยอดเยี่ยมสำหรับงานบ่มพื้นที่","ตัวควบคุมแยกต่างหาก ดีไซน์ที่ขยายขนาดได้"]} },
  "fl200": { intro: {"en": "A water-cooled, scalable, small form factor UV LED system with a separate controller and Ethernet control, designed for compact installation requirements.", "zh": "水冷式、可扩展、体积小巧的UV LED系统，配备独立控制器，支持以太网控制，专为紧凑安装需求设计。", "vi": "Hệ thống UV LED làm mát bằng nước, có thể mở rộng, kích thước nhỏ gọn với bộ điều khiển riêng và điều khiển Ethernet, được thiết kế cho yêu cầu lắp đặt nhỏ gọn.", "th": "ระบบ UV LED ระบายความร้อนด้วยน้ำ ที่ขยายขนาดได้และมีรูปทรงกะทัดรัด พร้อมตัวควบคุมแยกต่างหากและการควบคุมผ่าน Ethernet ออกแบบมาสำหรับการติดตั้งที่ต้องการความกะทัดรัด"}, features: {"en": ["Small form factor with separate controller", "Ethernet control for system integration"], "zh": ["体积小巧，配备独立控制器", "支持以太网控制，便于系统集成"], "vi": ["Kích thước nhỏ gọn với bộ điều khiển riêng", "Điều khiển Ethernet để tích hợp hệ thống"], "th": ["รูปทรงกะทัดรัด พร้อมตัวควบคุมแยกต่างหาก","การควบคุมผ่าน Ethernet เพื่อการผสานรวมระบบ"]} },
  "fl400": { intro: {"en": "A water-cooled, scalable UV LED system with digital/analog control, designed for high performance curing applications with optional Ethernet communication.", "zh": "水冷式、可扩展的UV LED系统，支持数字/模拟控制，专为高性能固化应用设计，并支持可选以太网通信。", "vi": "Hệ thống UV LED làm mát bằng nước, có thể mở rộng với điều khiển số/tương tự, được thiết kế cho ứng dụng đóng rắn hiệu suất cao với giao tiếp Ethernet tùy chọn.", "th": "ระบบ UV LED ระบายความร้อนด้วยน้ำที่ขยายขนาดได้ พร้อมการควบคุมแบบดิจิทัล/แอนะล็อก ออกแบบมาสำหรับงานบ่มประสิทธิภาพสูง พร้อมการสื่อสาร Ethernet เป็นตัวเลือก"}, features: {"en": ["Scalable design with digital/analog control", "Suited for high performance curing applications"], "zh": ["可扩展设计，支持数字/模拟控制", "适用于高性能固化应用"], "vi": ["Thiết kế mở rộng với điều khiển số/tương tự", "Phù hợp cho ứng dụng đóng rắn hiệu suất cao"], "th": ["ดีไซน์ที่ขยายขนาดได้ พร้อมการควบคุมแบบดิจิทัล/แอนะล็อก","เหมาะสำหรับงานบ่มประสิทธิภาพสูง"]} },
  "fl440": { intro: {"en": "A water-cooled, scalable UV LED system delivering high dose and high irradiance with digital/analog control, suited for high performance curing applications with optional Ethernet communication.", "zh": "水冷式、可扩展的UV LED系统，提供高剂量与高辐照度，支持数字/模拟控制，适用于高性能固化应用，并支持可选以太网通信。", "vi": "Hệ thống UV LED làm mát bằng nước, có thể mở rộng, mang lại liều cao và độ rọi cao với điều khiển số/tương tự, phù hợp cho ứng dụng đóng rắn hiệu suất cao với giao tiếp Ethernet tùy chọn.", "th": "ระบบ UV LED ระบายความร้อนด้วยน้ำที่ขยายขนาดได้ ให้ปริมาณรังสีสูงและความเข้มรังสีสูง พร้อมการควบคุมแบบดิจิทัล/แอนะล็อก เหมาะสำหรับงานบ่มประสิทธิภาพสูง พร้อมการสื่อสาร Ethernet เป็นตัวเลือก"}, features: {"en": ["High dose and high irradiance output", "Suited for high performance curing applications"], "zh": ["提供高剂量与高辐照度输出", "适用于高性能固化应用"], "vi": ["Đầu ra liều cao và độ rọi cao", "Phù hợp cho ứng dụng đóng rắn hiệu suất cao"], "th": ["เอาต์พุตปริมาณรังสีสูงและความเข้มรังสีสูง","เหมาะสำหรับงานบ่มประสิทธิภาพสูง"]} },
  "lighthammer-10": { intro: {"en": "The ultra high output 10-inch lamp system and flagship of the Fusion UV range, delivering the full 240 W/cm power class with electronic shutter, variable power control, and optional industrial fieldbus protocols. Represents the latest generation of LightHammer technology with CE compliance.", "zh": "超高输出10英寸灯具系统，是Fusion UV产品线的旗舰型号，提供全功率等级240 瓦/厘米，配备电子快门、可变功率控制及可选工业现场总线协议。代表LightHammer技术的最新一代，符合CE认证标准。", "vi": "Hệ thống đèn 10 inch đầu ra siêu cao và là sản phẩm chủ lực của dòng Fusion UV, cung cấp cấp công suất đầy đủ 240 W/cm với cửa chớp điện tử, điều khiển công suất biến thiên, và giao thức fieldbus công nghiệp tùy chọn. Đại diện cho thế hệ công nghệ LightHammer mới nhất, đạt chứng nhận CE.", "th": "ระบบหลอด 10 นิ้วเอาต์พุตสูงพิเศษและเป็นเรือธงของกลุ่มผลิตภัณฑ์ Fusion UV ให้กำลังระดับเต็ม 240 W/cm พร้อมชัตเตอร์อิเล็กทรอนิกส์ การควบคุมกำลังแบบปรับได้ และโปรโตคอลฟิลด์บัสอุตสาหกรรมเป็นตัวเลือก เป็นตัวแทนของเทคโนโลยี LightHammer รุ่นล่าสุดที่ได้มาตรฐาน CE"}, features: {"en": ["Ultra high output flagship of the Fusion UV product range", "Electronic shutter and variable power (35-100%)", "Optional industrial fieldbus protocol support"], "zh": ["Fusion UV产品线超高输出旗舰型号", "电子快门与可变功率（35-100%）", "可选支持工业现场总线协议"], "vi": ["Sản phẩm chủ lực đầu ra siêu cao của dòng Fusion UV", "Cửa chớp điện tử và công suất biến thiên (35-100%)", "Hỗ trợ giao thức fieldbus công nghiệp tùy chọn"], "th": ["เรือธงเอาต์พุตสูงพิเศษของกลุ่มผลิตภัณฑ์ Fusion UV","ชัตเตอร์อิเล็กทรอนิกส์และกำลังปรับได้ (35-100%)","รองรับโปรโตคอลฟิลด์บัสอุตสาหกรรมเป็นตัวเลือก"]} },
  "lighthammer-6": { intro: {"en": "A 6-inch electrodeless UV lamp system with variable power (35-100%) and quick restart, electronic shutter, and standard primary/secondary external control with optional industrial fieldbus protocols (DeviceNet, Profinet, Profibus, EtherNet/IP).", "zh": "采用6英寸灯泡的无极UV灯系统，支持可变功率（35-100%）及快速重启、电子快门，以及标配主/从外部控制，并可选配工业现场总线协议（DeviceNet、Profinet、Profibus、EtherNet/IP）。", "vi": "Hệ thống đèn UV không điện cực 6 inch với công suất biến thiên (35-100%) và khởi động lại nhanh, cửa chớp điện tử, và điều khiển ngoài chính/phụ tiêu chuẩn với giao thức fieldbus công nghiệp tùy chọn (DeviceNet, Profinet, Profibus, EtherNet/IP).", "th": "ระบบหลอด UV แบบไร้ขั้วอิเล็กโทรดขนาด 6 นิ้ว พร้อมกำลังปรับได้ (35-100%) และการรีสตาร์ตอย่างรวดเร็ว ชัตเตอร์อิเล็กทรอนิกส์ และการควบคุมภายนอกหลัก/รองมาตรฐาน พร้อมโปรโตคอลฟิลด์บัสอุตสาหกรรมเป็นตัวเลือก (DeviceNet, Profinet, Profibus, EtherNet/IP)"}, features: {"en": ["Variable power (35-100%) with quick restart capability", "Electronic shutter standard, optional mechanical", "Optional industrial fieldbus protocol support"], "zh": ["支持可变功率（35-100%），可快速重启", "标配电子快门，可选机械快门", "可选支持工业现场总线协议"], "vi": ["Công suất biến thiên (35-100%) với khả năng khởi động lại nhanh", "Cửa chớp điện tử tiêu chuẩn, tùy chọn cơ học", "Hỗ trợ giao thức fieldbus công nghiệp tùy chọn"], "th": ["กำลังปรับได้ (35-100%) พร้อมความสามารถรีสตาร์ตอย่างรวดเร็ว","ชัตเตอร์อิเล็กทรอนิกส์เป็นมาตรฐาน มีชัตเตอร์เชิงกลเป็นตัวเลือก","รองรับโปรโตคอลฟิลด์บัสอุตสาหกรรมเป็นตัวเลือก"]} },
  "ls200": { intro: {"en": "UV LED radiometry and calibration at the cure site — ±10% accuracy, 1 mW/cm² resolution, NRC-traceable sensors, LX500 integration.", "zh": "在固化位置直接测量与校准 UV LED：精度 ±10%、分辨率 1 mW/cm²，NRC 溯源传感器，可与 LX500 无缝集成。", "vi": "Đo và hiệu chuẩn UV LED ngay tại điểm curing — chính xác ±10%, phân giải 1 mW/cm², cảm biến chuẩn NRC, tích hợp LX500.", "th": "วัดและสอบเทียบ UV LED ณ จุดบ่มโดยตรง — ความแม่นยำ ±10% ความละเอียด 1 mW/cm² เซนเซอร์สอบกลับ NRC ใช้กับ LX500 ได้"}, features: {"en": ["Accurate measurement with +/-10% accuracy and high resolution", "Optimized for monochromatic UV LED sources", "Compact design suitable for confined-area measurements"], "zh": ["测量精准，误差±10%，分辨率高", "针对单色UV LED光源优化", "紧凑设计，适合狭小空间测量"], "vi": ["Đo chính xác với độ chính xác +/-10% và độ phân giải cao", "Tối ưu cho nguồn UV LED đơn sắc", "Thiết kế nhỏ gọn phù hợp đo trong không gian hẹp"], "th": ["การวัดที่แม่นยำด้วยความแม่นยำ +/-10% และความละเอียดสูง","ปรับให้เหมาะกับแหล่งกำเนิด UV LED แบบสีเดียว","ดีไซน์กะทัดรัด เหมาะสำหรับการวัดในพื้นที่จำกัด"]} },
  "lx505": { intro: {"en": "The next-generation UV LED spot curing system — ±5% optical stability, LED cooling, StepCure® 2.0 multi-step control and new color-coded LED MAX heads for fast, uniform, repeatable curing.", "zh": "新一代 UV LED 点固化系统——±5% 光学稳定、LED 冷却、StepCure® 2.0 多步编程,配全新彩码 LED MAX 灯头,固化快速、均匀、可重复。", "vi": "Hệ thống UV LED spot curing thế hệ mới — ổn định quang ±5%, làm mát LED, điều khiển đa bước StepCure® 2.0 và đầu LED MAX mã màu mới, curing nhanh, đều, lặp lại.", "th": "ระบบบ่มแบบจุด UV LED เจเนอเรชันใหม่ — เสถียรเชิงแสง ±5%, ระบายความร้อน LED, ควบคุมหลายขั้นตอน StepCure® 2.0 และหัว LED MAX รหัสสีใหม่ บ่มเร็ว สม่ำเสมอ ทำซ้ำได้"}, features: {"en": ["±5% optical stability with LED cooling that monitors head temperature and life data", "StepCure® 2.0 — program exposure time, intensity, duty cycle and trigger per channel across single or multiple heads", "Color-coded LED MAX heads (55 & 130 mm) at 365 / 385 / 400 nm cut setup time", "2.4-inch full-color LCD with 4-way keypad, PLC, or USB control"], "zh": ["±5% 光学稳定,LED 冷却可监控灯头温度与寿命数据", "StepCure® 2.0——每通道可编程曝光时间、强度、占空比与触发,支持单/多灯头", "彩码 LED MAX 灯头(55/130mm),365/385/400nm,缩短设置时间", "2.4 英寸全彩屏,支持四向按键、PLC 或 USB 控制"], "vi": ["Ổn định quang ±5% với làm mát LED giám sát nhiệt độ và tuổi thọ đầu đèn", "StepCure® 2.0 — lập trình thời gian phơi, cường độ, chu kỳ và kích hoạt theo từng kênh, đơn hoặc nhiều đầu", "Đầu LED MAX mã màu (55 & 130 mm) ở 365 / 385 / 400 nm giảm thời gian cài đặt", "Màn hình LCD màu 2.4 inch, điều khiển bàn phím 4 hướng, PLC hoặc USB"], "th": ["เสถียรเชิงแสง ±5% พร้อมระบายความร้อน LED ที่ตรวจสอบอุณหภูมิและอายุหัวไฟ", "StepCure® 2.0 — ตั้งเวลาฉาย ความเข้ม duty cycle และทริกเกอร์ต่อแชนเนล ทั้งหัวเดียวหรือหลายหัว", "หัว LED MAX รหัสสี (55 & 130 มม.) ที่ 365 / 385 / 400 nm ลดเวลาตั้งค่า", "จอ LCD สีเต็ม 2.4 นิ้ว ควบคุมด้วยแป้น 4 ทิศทาง PLC หรือ USB"]} },
  "lx500": { intro: {"en": "Ultra-compact UV LED spot curing — ±5% optical stability, up to 27 W/cm², 2 or 4 channels, built for consistent, repeatable curing.", "zh": "超紧凑 UV LED 点光源固化：±5% 光学稳定性，峰值光强达 27 W/cm²，2/4 通道，固化一致、可重复。", "vi": "UV LED spot curing siêu nhỏ gọn — ổn định quang học ±5%, đỉnh 27 W/cm², 2/4 kênh, curing đồng nhất và lặp lại.", "th": "ระบบบ่มแบบจุด UV LED ขนาดกะทัดรัด — เสถียรภาพแสง ±5% ความเข้มสูงสุด 27 W/cm² แบบ 2/4 แชนเนล บ่มสม่ำเสมอ ทำซ้ำได้"}, features: {"en": ["Intelli-Lamp LED technology maintains optical stability +/-5% during exposure", "Integrated radiometer for quick calibration and accurate intensity measurement", "2.4-inch full color LCD with four-way keypad, foot pedal, PLC, or USB control"], "zh": ["Intelli-Lamp LED技术在曝光过程中保持±5%的光学稳定性", "集成辐射计，实现快速校准与精准强度测量", "2.4英寸全彩液晶屏，支持四向按键、脚踏、PLC或USB多种控制方式"], "vi": ["Công nghệ Intelli-Lamp LED duy trì độ ổn định quang học +/-5% trong khi phơi sáng", "Máy đo bức xạ tích hợp để hiệu chuẩn nhanh và đo cường độ chính xác", "Màn hình LCD màu 2.4 inch với điều khiển bàn phím 4 hướng, bàn đạp, PLC hoặc USB"], "th": ["เทคโนโลยี Intelli-Lamp LED รักษาความเสถียรทางแสง +/-5% ระหว่างการฉายแสง","เครื่องวัดรังสีในตัวเพื่อการสอบเทียบที่รวดเร็วและการวัดความเข้มที่แม่นยำ","จอ LCD สีเต็มรูปแบบขนาด 2.4 นิ้ว พร้อมการควบคุมด้วยแป้นกดสี่ทิศทาง แป้นเหยียบ PLC หรือ USB"]} },
  "nexus-ii": { intro: {"en": "A water-cooled high power UV LED system offering quiet operation and rugged reliability in tough environments, with Ethernet communications and easy mounting with a common form factor. Well suited to flexographic printing applications.", "zh": "水冷式高功率UV LED系统，运行安静，在恶劣环境下坚固可靠，支持以太网通信，采用通用结构便于安装。适用于柔印等印刷应用场景。", "vi": "Hệ thống UV LED công suất cao làm mát bằng nước, vận hành êm ái và bền bỉ trong môi trường khắc nghiệt, hỗ trợ giao tiếp Ethernet và dễ lắp đặt với kích thước tiêu chuẩn. Phù hợp cho ứng dụng in flexo.", "th": "ระบบ UV LED กำลังสูงระบายความร้อนด้วยน้ำ ทำงานเงียบและทนทานเชื่อถือได้ในสภาพแวดล้อมที่รุนแรง พร้อมการสื่อสาร Ethernet และการติดตั้งที่ง่ายด้วยรูปทรงมาตรฐาน เหมาะอย่างยิ่งสำหรับงานพิมพ์เฟล็กโซกราฟิก"}, features: {"en": ["Higher dose than the air-cooled variant — highest total UV energy for flexographic printing", "Wider web: up to 675 mm, with print speeds up to 1050 ft (320 m)/min", "90 W per cm maximum electrical power; >60,000 h diode life at L90", "ValidCure Technology; up to 60% less energy; 5-year full-system warranty"], "zh": ["剂量高于风冷版本——柔印领域最高总UV能量", "更宽幅面:最宽达675 mm，印刷速度可达1050 ft (320 m)/min", "最大电功率90 W/cm;二极管寿命>60,000小时(L90)", "ValidCure技术;节电达60%;整机5年质保"], "vi": ["Liều cao hơn phiên bản làm mát bằng khí — tổng năng lượng UV cao nhất cho in flexo", "Khổ rộng hơn: đến 675 mm, tốc độ in đến 1050 ft (320 m)/phút", "Công suất điện tối đa 90 W/cm; tuổi thọ diode >60.000 giờ (L90)", "Công nghệ ValidCure; tiết kiệm đến 60% điện; bảo hành toàn hệ thống 5 năm"], "th": ["ปริมาณรังสีสูงกว่ารุ่นระบายความร้อนด้วยอากาศ — พลังงาน UV รวมสูงสุดสำหรับงานพิมพ์เฟล็กโซกราฟิก","หน้ากว้างขึ้น: สูงสุด 675 mm ด้วยความเร็วพิมพ์สูงสุด 1050 ft (320 m)/min","กำลังไฟฟ้าสูงสุด 90 W per cm; อายุไดโอด >60,000 h ที่ L90","เทคโนโลยี ValidCure; ประหยัดพลังงานได้ถึง 60%; รับประกันทั้งระบบ 5 ปี"]} },
  "nexus-ii-ac": { intro: {"en": "An air-cooled UV LED system with reduced routine maintenance and no chiller needed, offering Ethernet communications and easy mounting with a common form factor. Well suited to flexographic printing applications.", "zh": "风冷式UV LED系统，日常维护需求更低，无需配置冷水机，支持以太网通信，采用通用结构便于安装。适用于柔印等印刷应用场景。", "vi": "Hệ thống UV LED làm mát bằng khí giảm bảo trì định kỳ và không cần máy làm lạnh, hỗ trợ giao tiếp Ethernet và dễ lắp đặt với kích thước tiêu chuẩn. Phù hợp cho ứng dụng in flexo.", "th": "ระบบ UV LED ระบายความร้อนด้วยอากาศ ที่ลดการบำรุงรักษาตามปกติและไม่ต้องใช้เครื่องทำความเย็น พร้อมการสื่อสาร Ethernet และการติดตั้งที่ง่ายด้วยรูปทรงมาตรฐาน เหมาะอย่างยิ่งสำหรับงานพิมพ์เฟล็กโซกราฟิก"}, features: {"en": ["No chiller or blower needed — the most energy-efficient Nexus II (up to 70% less kWh)", "Web width 300 – 600 mm; print speeds up to 720 ft (220 m)/min", "65 W per cm maximum electrical power; 45 °C maximum operating temperature", "ValidCure Technology; quick retrofit to any press; 5-year full-system warranty"], "zh": ["无需冷水机或风机——Nexus II中最节能型号(节电达70%)", "幅面300 – 600 mm;印刷速度可达720 ft (220 m)/min", "最大电功率65 W/cm;最高工作温度45°C", "ValidCure技术;快速加装到任意印刷机;整机5年质保"], "vi": ["Không cần máy làm lạnh hay quạt thổi — Nexus II tiết kiệm điện nhất (giảm đến 70% kWh)", "Khổ rộng 300 – 600 mm; tốc độ in đến 720 ft (220 m)/phút", "Công suất điện tối đa 65 W/cm; nhiệt độ vận hành tối đa 45 °C", "Công nghệ ValidCure; lắp thêm nhanh vào mọi máy in; bảo hành toàn hệ thống 5 năm"], "th": ["ไม่ต้องใช้เครื่องทำความเย็นหรือพัดลม — Nexus II ที่ประหยัดพลังงานที่สุด (ลด kWh ได้ถึง 70%)","หน้ากว้าง 300 – 600 mm; ความเร็วพิมพ์สูงสุด 720 ft (220 m)/min","กำลังไฟฟ้าสูงสุด 65 W per cm; อุณหภูมิทำงานสูงสุด 45 °C","เทคโนโลยี ValidCure; ติดตั้งเพิ่มเข้ากับแท่นพิมพ์ใดก็ได้อย่างรวดเร็ว; รับประกันทั้งระบบ 5 ปี"]} },
  "r2000": { intro: {"en": "The reference radiometer for OmniCure spot curing — real-time NIST-accurate calibration with the S2000 Elite, plus cure-site and cure-ring sensors.", "zh": "OmniCure 点固化的基准辐照计：与 S2000 Elite 实时校准达 NIST 精度，支持固化位与固化环专用传感器。", "vi": "Radiometer chuẩn cho OmniCure spot curing — hiệu chuẩn thời gian thực đạt độ chính xác NIST cùng S2000 Elite, hỗ trợ cảm biến cure-site/cure-ring.", "th": "เรดิโอมิเตอร์อ้างอิงของ OmniCure — สอบเทียบเรียลไทม์ความแม่นยำระดับ NIST คู่กับ S2000 Elite รองรับเซนเซอร์ cure-site และ cure-ring"}, features: {"en": ["Combines with S2000 Elite/S2000 for complete curing station control", "Supports custom sensors for cure site and cure ring measurement"], "zh": ["可与S2000 Elite/S2000配合，组成完整固化工作站控制方案", "支持连接定制传感器，用于固化点和固化环测量"], "vi": ["Kết hợp với S2000 Elite/S2000 để kiểm soát trạm đóng rắn hoàn chỉnh", "Hỗ trợ cảm biến tùy chỉnh để đo tại điểm đóng rắn và vòng đóng rắn"], "th": ["ผสานกับ S2000 Elite/S2000 เพื่อการควบคุมสถานีบ่มที่สมบูรณ์","รองรับเซนเซอร์ที่ปรับแต่งได้สำหรับการวัดที่จุดบ่มและวงแหวนบ่ม"]} },
  "s1500-pro": { intro: {"en": "200 W lamp-based UV spot curing for automated lines — 2,000-hour guaranteed lamp, StepCure 2.0 profiles, 4.3-inch touch screen, PLC output.", "zh": "面向自动化产线的 200 W 点固化：灯管保证 2,000 小时，StepCure 2.0 多段曲线，4.3 英寸触屏与 PLC 输出。", "vi": "Spot curing 200 W cho dây chuyền tự động — bảo hành đèn 2.000 giờ, StepCure 2.0, màn hình cảm ứng 4,3 inch, đầu ra PLC.", "th": "ระบบบ่มแบบจุด 200 W สำหรับไลน์อัตโนมัติ — รับประกันหลอด 2,000 ชม. StepCure 2.0 จอสัมผัส 4.3 นิ้ว และเอาต์พุต PLC"}, features: {"en": ["Intelli-Lamp 2.0 technology enhances lamp life while maintaining performance", "User-interchangeable and customizable optical filters", "Industry 4.0 ready with programmable PLC output, Flight Recorder log, and NFC key card"], "zh": ["Intelli-Lamp 2.0技术延长灯泡寿命同时保持性能", "用户可更换、可定制的光学滤镜", "支持工业4.0，配备可编程PLC输出、飞行记录器日志和NFC密钥卡"], "vi": ["Công nghệ Intelli-Lamp 2.0 kéo dài tuổi thọ đèn trong khi duy trì hiệu suất", "Bộ lọc quang có thể thay thế và tùy chỉnh bởi người dùng", "Sẵn sàng Industry 4.0 với đầu ra PLC lập trình được, nhật ký Flight Recorder và thẻ khóa NFC"], "th": ["เทคโนโลยี Intelli-Lamp 2.0 ยืดอายุหลอดพร้อมคงประสิทธิภาพ","ฟิลเตอร์ออปติกที่ผู้ใช้เปลี่ยนเองและปรับแต่งได้","พร้อมสำหรับ Industry 4.0 ด้วยเอาต์พุต PLC ที่ตั้งโปรแกรมได้ บันทึก Flight Recorder และบัตรกุญแจ NFC"]} },
  "s2000-elite": { intro: {"en": "Flagship 200 W lamp-based UV spot curing — Closed-Loop Feedback holds output within ±5%, 30 ms shutter, Industry 4.0 connectivity.", "zh": "旗舰 200 W 灯管式点固化：闭环反馈把输出稳定在 ±5%，30 ms 快门，支持 Industry 4.0（以太网、NFC、PLC）。", "vi": "Spot curing đèn 200 W hàng đầu — Closed-Loop Feedback giữ đầu ra ±5%, màn trập 30 ms, kết nối Industry 4.0 (Ethernet, NFC, PLC).", "th": "ระบบบ่มแบบจุดหลอด 200 W เรือธง — Closed-Loop Feedback คุมเอาต์พุต ±5% ชัตเตอร์ 30 ms พร้อม Industry 4.0 (Ethernet, NFC, PLC)"}, features: {"en": ["Closed-Loop Feedback and Intelli-lamp technology guarantee precise dosage delivery", "Plug-and-play compatibility with existing S2000/S1500 production lines", "Calibration with OmniCure R2000 Radiometer, remote control via WEB UI", "StepCure 2.0 with PLC control enhances automation for Industry 4.0"], "zh": ["闭环反馈与Intelli-lamp技术确保精准剂量输出", "即插即用，兼容现有S2000/S1500生产线", "可配合OmniCure R2000辐射计校准，支持WEB UI远程控制管理", "StepCure 2.0配合PLC控制，提升自动化水平，适配工业4.0"], "vi": ["Công nghệ phản hồi vòng kín và Intelli-lamp đảm bảo cấp liều chính xác", "Tương thích cắm-và-chạy với dây chuyền sản xuất S2000/S1500 hiện có", "Hiệu chuẩn cùng máy đo bức xạ OmniCure R2000, điều khiển từ xa qua WEB UI", "StepCure 2.0 với điều khiển PLC tăng cường tự động hóa cho Industry 4.0"], "th": ["เทคโนโลยี Closed-Loop Feedback และ Intelli-lamp รับประกันการจ่ายปริมาณรังสีที่แม่นยำ","รองรับแบบ Plug-and-play เข้ากับสายการผลิต S2000/S1500 ที่มีอยู่","สอบเทียบด้วยเครื่องวัดรังสี OmniCure R2000 ควบคุมระยะไกลผ่าน WEB UI","StepCure 2.0 พร้อมการควบคุม PLC ช่วยเพิ่มระบบอัตโนมัติสำหรับ Industry 4.0"]} },
  "semray-5000": { intro: {"en": "Designed for higher performance and flexible integration especially for larger working distances, the Semray UV5000+ Series is a water-cooled system. The emission window size is scalable in width from 400 to 1300mm in 50mm steps, with housing dimensions scalable accordingly.", "zh": "Semray UV5000+系列为水冷式系统，专为更高性能与灵活集成而设计，尤其适合较大工作距离的应用场景。发光窗口宽度可在400至1300毫米范围内以50毫米为步进进行调整，外壳尺寸相应可调。", "vi": "Được thiết kế cho hiệu suất cao hơn và tích hợp linh hoạt, đặc biệt phù hợp với khoảng cách làm việc lớn hơn, dòng Semray UV5000+ là hệ thống làm mát bằng nước. Kích thước cửa sổ phát quang có thể điều chỉnh theo chiều rộng từ 400 đến 1300mm theo bước 50mm, kích thước vỏ máy điều chỉnh tương ứng.", "th": "ออกแบบมาเพื่อประสิทธิภาพที่สูงขึ้นและการผสานรวมที่ยืดหยุ่น โดยเฉพาะสำหรับระยะทำงานที่ไกลขึ้น ซีรีส์ Semray UV5000+ เป็นระบบระบายความร้อนด้วยน้ำ ขนาดหน้าต่างปล่อยแสงปรับความกว้างได้จาก 400 ถึง 1300mm ทีละขั้น 50mm พร้อมขนาดตัวเรือนที่ปรับตามได้"}, features: {"en": ["Designed for larger working distances with flexible integration", "Emission window scalable from 400 to 1300mm in 50mm steps"], "zh": ["专为大工作距离与灵活集成而设计", "发光窗口宽度可在400至1300毫米之间以50毫米为步进调整"], "vi": ["Thiết kế cho khoảng cách làm việc lớn với tích hợp linh hoạt", "Cửa sổ phát quang điều chỉnh từ 400 đến 1300mm theo bước 50mm"], "th": ["ออกแบบมาสำหรับระยะทำงานไกลขึ้นพร้อมการผสานรวมที่ยืดหยุ่น","หน้าต่างปล่อยแสงปรับได้จาก 400 ถึง 1300mm ทีละขั้น 50mm"]} },
  "semray-pc6003": { intro: {"en": "A UV LED curing system designed from the ground up for optical fiber draw and wire marking manufacturing processes, providing 360° curing coverage.", "zh": "UV PC6003是一款从零开始专为光纤拉丝与线材标识制造工艺设计的UV LED固化系统，提供360°全方位固化覆盖。", "vi": "Hệ thống đóng rắn UV LED được thiết kế từ đầu cho quy trình sản xuất kéo sợi quang và đánh dấu dây, cung cấp phạm vi đóng rắn 360°.", "th": "ระบบบ่ม UV LED ที่ออกแบบขึ้นใหม่ทั้งหมดสำหรับกระบวนการผลิตการดึงเส้นใยแก้วนำแสงและการทำเครื่องหมายบนสายไฟ ให้ความครอบคลุมการบ่ม 360°"}, features: {"en": ["Purpose-built for optical fiber draw and wire marking processes", "360° curing coverage"], "zh": ["专为光纤拉丝与线材标识工艺打造", "360°全方位固化覆盖"], "vi": ["Được chế tạo riêng cho quy trình kéo sợi quang và đánh dấu dây", "Phạm vi đóng rắn 360°"], "th": ["สร้างขึ้นเฉพาะสำหรับกระบวนการดึงเส้นใยแก้วนำแสงและการทำเครื่องหมายบนสายไฟ","ความครอบคลุมการบ่ม 360°"]} },
  "semray-uv5052m": { intro: {"en": "Equipped with special optics to bring more energy to the process, the Semray UV5052M is an example of customized UV LED development. A set of unique optical concepts direct photons from the UV-LED chips to larger working distances for greater flexibility in applications, minimum loss of energy and straylight, and focused UV intensity.", "zh": "UV5052M配备特殊光学系统，可为工艺过程提供更高能量，是Semray定制化UV LED开发的代表案例之一。独特的光学设计可将UV-LED芯片发出的光子引导至更大的工作距离，从而提升应用灵活性、最大限度降低能量损耗与杂散光，并实现聚焦的UV强度输出。", "vi": "Được trang bị quang học đặc biệt để mang lại nhiều năng lượng hơn cho quy trình, Semray UV5052M là ví dụ điển hình của phát triển UV LED tùy chỉnh. Một loạt khái niệm quang học độc đáo định hướng photon từ chip UV-LED đến khoảng cách làm việc lớn hơn, mang lại tính linh hoạt cao hơn trong ứng dụng, giảm thiểu thất thoát năng lượng và tán xạ, và cường độ UV tập trung.", "th": "ติดตั้งระบบออปติกพิเศษเพื่อนำพลังงานเข้าสู่กระบวนการมากขึ้น Semray UV5052M เป็นตัวอย่างของการพัฒนา UV LED แบบปรับแต่งเฉพาะ ชุดแนวคิดออปติกที่เป็นเอกลักษณ์นำโฟตอนจากชิป UV-LED ไปยังระยะทำงานที่ไกลขึ้น เพื่อความยืดหยุ่นที่มากขึ้นในการใช้งาน ลดการสูญเสียพลังงานและแสงกระเจิงให้น้อยที่สุด และให้ความเข้ม UV ที่โฟกัส"}, features: {"en": ["Dedicated optics for high intensity even at large working distances", "Customizable in sizes, lengths, connections, and optical concepts"], "zh": ["专用光学设计，即使在大工作距离下也能保持高强度", "尺寸、长度、接口及光学方案均可定制"], "vi": ["Quang học chuyên dụng cho cường độ cao ngay cả ở khoảng cách làm việc lớn", "Có thể tùy chỉnh về kích thước, chiều dài, kết nối và khái niệm quang học"], "th": ["ระบบออปติกเฉพาะสำหรับความเข้มสูงแม้ที่ระยะทำงานไกล","ปรับแต่งได้ทั้งขนาด ความยาว การเชื่อมต่อ และแนวคิดออปติก"]} },
  "vericure": { intro: {"en": "A water-cooled UV LED system delivering ultra-high UV dose in a wide lamp format, up to 500 mJ/cm2 dose at 50mm working distance. Offers quiet operation and rugged reliability in tough environments, with Ethernet and analog communications. Well suited to high performance applications such as wood coatings.", "zh": "水冷式UV LED系统，以宽幅灯具形式提供超高UV剂量，工作距离50毫米时剂量最高可达500 mJ/cm²。运行安静，在恶劣环境下坚固可靠，支持以太网与模拟通信。适用于木材涂层等高性能应用场景。", "vi": "Hệ thống UV LED làm mát bằng nước cung cấp liều UV siêu cao ở định dạng đèn rộng, đạt tới 500 mJ/cm² ở khoảng cách làm việc 50mm. Vận hành êm ái và độ bền cao trong môi trường khắc nghiệt, hỗ trợ giao tiếp Ethernet và tương tự. Phù hợp cho ứng dụng hiệu suất cao như sơn phủ gỗ.", "th": "ระบบ UV LED ระบายความร้อนด้วยน้ำ ให้ปริมาณรังสี UV ที่สูงเป็นพิเศษในรูปแบบหลอดหน้ากว้าง สูงสุด 500 mJ/cm2 ที่ระยะทำงาน 50mm ทำงานเงียบและทนทานเชื่อถือได้ในสภาพแวดล้อมที่รุนแรง พร้อมการสื่อสาร Ethernet และแอนะล็อก เหมาะอย่างยิ่งสำหรับงานประสิทธิภาพสูง เช่น การเคลือบไม้"}, features: {"en": ["Ultra-high UV dose up to 500 mJ/cm2 at 50mm working distance", "Quiet operation, rugged and reliable in tough environments", "Ethernet and analog communications, easy mounting with common form factor"], "zh": ["超高UV剂量，50毫米工作距离下最高可达500 mJ/cm²", "运行安静，在恶劣环境下坚固可靠", "支持以太网与模拟通信，采用通用结构便于安装"], "vi": ["Liều UV siêu cao lên đến 500 mJ/cm² ở khoảng cách làm việc 50mm", "Vận hành êm ái, bền bỉ và đáng tin cậy trong môi trường khắc nghiệt", "Giao tiếp Ethernet và tương tự, dễ lắp đặt với kích thước tiêu chuẩn"], "th": ["ปริมาณรังสี UV สูงเป็นพิเศษ สูงสุด 500 mJ/cm2 ที่ระยะทำงาน 50mm","ทำงานเงียบ ทนทานและเชื่อถือได้ในสภาพแวดล้อมที่รุนแรง","การสื่อสาร Ethernet และแอนะล็อก ติดตั้งง่ายด้วยรูปทรงมาตรฐาน"]} },
  "v3-led-heads": { intro: {"en": "Next-generation LED heads for the LX500 — up to 22 W/cm² and 1,100 mW at 365–405 nm, with an exceptionally uniform beam.", "zh": "LX500 专用新一代 LED 灯头：365–405 nm，峰值光强达 22 W/cm²、光功率 1,100 mW，光斑均匀，固化更快更稳定。", "vi": "Đầu LED thế hệ mới cho LX500 — 365–405 nm, đỉnh 22 W/cm², 1.100 mW, chùm tia đồng đều, curing nhanh và ổn định hơn.", "th": "หัว LED รุ่นใหม่สำหรับ LX500 — 365–405 nm ความเข้มสูงสุด 22 W/cm² กำลัง 1,100 mW ลำแสงสม่ำเสมอ บ่มเร็วและคงที่"}, features: {"en": ["Class-leading irradiance and optical power at 365, 385, 395 and 405 nm", "Up to 22 W/cm² peak irradiance and 1,100 mW total optical power", "Improved radiation distribution across the beam cross-section for consistent, controlled curing", "Up to 120% increased optical power vs. predecessor MAX LED Heads", "More energy efficient, lower maintenance, and longer service life", "Wide range of cross-compatible accessories: focusing lenses, adapters, extension cables", "Backward compatible with existing LX500 Controller", "Paired with LX500 for outstanding ±5% optical stability"], "zh": ["在 365、385、395 和 405 nm 下具有同类领先的辐照度和光功率", "峰值辐照度最高达 22 W/cm²，总光功率达 1,100 mW", "改善光束横截面的辐射分布，实现一致、可控的固化", "与上一代 MAX LED Heads 相比，光功率提升最高达 120%", "更节能、更低维护、更长使用寿命", "多种交叉兼容配件：聚焦透镜、适配器、延长线缆", "向后兼容现有的 LX500 Controller", "与 LX500 搭配使用，实现出色的 ±5% 光学稳定性"], "vi": ["Độ rọi và công suất quang hàng đầu phân khúc ở 365, 385, 395 và 405 nm", "Độ rọi đỉnh tới 22 W/cm² và tổng công suất quang 1,100 mW", "Cải thiện phân bố bức xạ trên tiết diện chùm tia để đóng rắn đồng nhất và có kiểm soát", "Công suất quang tăng tới 120% so với MAX LED Heads thế hệ trước", "Tiết kiệm năng lượng hơn, bảo trì ít hơn và tuổi thọ dài hơn", "Nhiều phụ kiện tương thích chéo: thấu kính hội tụ, bộ chuyển đổi, cáp nối dài", "Tương thích ngược với LX500 Controller hiện có", "Kết hợp với LX500 để đạt độ ổn định quang ±5% xuất sắc"], "th": ["ความเข้มรังสีและกำลังแสงชั้นนำในระดับเดียวกันที่ 365, 385, 395 และ 405 nm","ความเข้มรังสีสูงสุดถึง 22 W/cm² และกำลังแสงรวม 1,100 mW","การกระจายรังสีที่ดีขึ้นทั่วหน้าตัดลำแสงเพื่อการบ่มที่สม่ำเสมอและควบคุมได้","กำลังแสงเพิ่มขึ้นถึง 120% เทียบกับ MAX LED Heads รุ่นก่อนหน้า","ประหยัดพลังงานมากขึ้น บำรุงรักษาน้อยลง และอายุการใช้งานยาวนานขึ้น","อุปกรณ์เสริมที่เข้ากันได้หลากหลาย: เลนส์โฟกัส อะแดปเตอร์ สายต่อขยาย","เข้ากันได้ย้อนหลังกับ LX500 Controller ที่มีอยู่","จับคู่กับ LX500 เพื่อความเสถียรทางแสง ±5% ที่ยอดเยี่ยม"]} },
  "s2e-network-module": { intro: {"en": "Ethernet adapter for S-Series spot curing — remotely monitor and control up to 300 systems via the OmniCure Monitoring Station software.", "zh": "S 系列专用以太网模块：通过 OmniCure 监控软件在局域网内远程监控与控制多达 300 台固化系统。", "vi": "Mô-đun Ethernet cho dòng S — giám sát và điều khiển từ xa tối đa 300 hệ thống qua phần mềm OmniCure Monitoring Station.", "th": "โมดูล Ethernet สำหรับ S-Series — ตรวจสอบและควบคุมระยะไกลได้ถึง 300 เครื่องผ่านซอฟต์แวร์ OmniCure Monitoring Station"}, features: {"en": ["Save maintenance time and keep production running smoothly with OmniCure Monitoring Station software", "Proactively trend and predict maintenance requirements with continuous operational data logging", "Enhance visibility of production activity and quickly isolate issues that result in potential waste/rework", "Increase productivity and eliminate time lost identifying system faults with real-time email alerts", "Remotely access and monitor up to 300 UV curing systems on a local area network", "Adds StepCure process functionality to the S1500"], "zh": ["借助 OmniCure Monitoring Station 软件节省维护时间并保持生产顺畅运行", "通过持续的运行数据记录，主动分析趋势并预测维护需求", "提升生产活动的可视性，快速定位可能导致浪费/返工的问题", "通过实时邮件警报提高生产率，消除识别系统故障所浪费的时间", "在局域网上远程访问和监控多达 300 台 UV Curing 紫外线固化系统", "为 S1500 增加 StepCure 工艺功能"], "vi": ["Tiết kiệm thời gian bảo trì và giữ sản xuất vận hành trơn tru với phần mềm OmniCure Monitoring Station", "Chủ động phân tích xu hướng và dự đoán nhu cầu bảo trì với ghi dữ liệu vận hành liên tục", "Tăng khả năng hiển thị hoạt động sản xuất và nhanh chóng khoanh vùng các vấn đề có thể gây lãng phí/làm lại", "Tăng năng suất và loại bỏ thời gian mất đi khi xác định lỗi hệ thống nhờ cảnh báo email theo thời gian thực", "Truy cập và giám sát từ xa tới 300 hệ thống đóng rắn UV trên mạng cục bộ", "Bổ sung chức năng quy trình StepCure cho S1500"], "th": ["ประหยัดเวลาบำรุงรักษาและให้การผลิตดำเนินไปอย่างราบรื่นด้วยซอฟต์แวร์ OmniCure Monitoring Station","วิเคราะห์แนวโน้มและคาดการณ์ความต้องการบำรุงรักษาเชิงรุกด้วยการบันทึกข้อมูลการทำงานอย่างต่อเนื่อง","เพิ่มการมองเห็นกิจกรรมการผลิตและระบุปัญหาที่อาจก่อให้เกิดของเสีย/การทำซ้ำได้อย่างรวดเร็ว","เพิ่มผลิตภาพและขจัดเวลาที่สูญเสียไปกับการระบุข้อบกพร่องของระบบด้วยการแจ้งเตือนทางอีเมลแบบเรียลไทม์","เข้าถึงและตรวจสอบระบบ UV Curing ได้จากระยะไกลสูงสุด 300 ระบบบนเครือข่ายท้องถิ่น","เพิ่มฟังก์ชันกระบวนการ StepCure ให้กับ S1500"]} },
  "fl400-i": { intro: {"en": "FL400 performance in an IP66 industrial enclosure — sealed optics and optional sacrificial glass for harsh, high-contaminant environments.", "zh": "FL400 性能装进 IP66 工业外壳：密封光学与可选牺牲玻璃，专为管道涂装、金属表面等高污染严苛环境设计。", "vi": "Hiệu năng FL400 trong vỏ IP66 — quang học kín và kính bảo vệ tùy chọn cho môi trường khắc nghiệt như phủ ống, hoàn thiện kim loại.", "th": "สมรรถนะ FL400 ในตัวถัง IP66 — ออปติกซีลแน่นและกระจกป้องกันเสริม สำหรับงานเคลือบท่อและสภาพแวดล้อมปนเปื้อนสูง"}, features: {"en": ["IP66-rated ruggedized enclosure for harsh, high-contaminant environments", "Advanced window sealing protects against heat, liquid, and dirt intrusion", "Versatile connection options: straight or barbed water fittings", "CDA (clean, dry air) ports to protect against condensation", "Optional sacrificial glass to shield primary optics", "Same optical uniformity and high dose performance as FL400", "Robust endcaps engineered for challenging industrial environments"], "zh": ["IP66 级坚固外壳，适用于严苛、高污染环境", "先进的窗口密封，防止热量、液体和污垢侵入", "多样的连接选项：直式或倒钩式水接头", "CDA（清洁干燥空气）端口，防止冷凝", "可选牺牲玻璃(保护玻璃)，保护主光学元件", "与 FL400 相同的光学均匀性和高剂量性能", "坚固的端盖，专为严苛的工业环境设计"], "vi": ["Vỏ gia cố đạt chuẩn IP66 cho môi trường khắc nghiệt, nhiều chất bẩn", "Gioăng kín cửa sổ tiên tiến bảo vệ chống nhiệt, chất lỏng và bụi bẩn xâm nhập", "Tùy chọn kết nối đa dạng: khớp nối nước thẳng hoặc có ngạnh", "Cổng CDA (khí sạch, khô) để chống ngưng tụ", "Kính bảo vệ tùy chọn để che chắn quang học chính", "Độ đồng đều quang học và hiệu suất liều cao giống như FL400", "Nắp đầu chắc chắn được thiết kế cho môi trường công nghiệp đầy thách thức"], "th": ["ตัวเรือนเสริมความแข็งแรงมาตรฐาน IP66 สำหรับสภาพแวดล้อมที่รุนแรงและมีสิ่งปนเปื้อนสูง","ซีลหน้าต่างขั้นสูงป้องกันการซึมของความร้อน ของเหลว และสิ่งสกปรก","ตัวเลือกการเชื่อมต่อที่หลากหลาย: ข้อต่อน้ำแบบตรงหรือแบบหยัก","พอร์ต CDA (อากาศสะอาดและแห้ง) เพื่อป้องกันการควบแน่น","กระจกป้องกันเป็นตัวเลือกเพื่อปกป้องออปติกหลัก","ความสม่ำเสมอทางแสงและประสิทธิภาพปริมาณรังสีสูงเช่นเดียวกับ FL400","ฝาปิดปลายที่แข็งแรง ออกแบบมาสำหรับสภาพแวดล้อมอุตสาหกรรมที่ท้าทาย"]} },
  "fe400": { intro: {"en": "Air-cooled curing and pinning with built-in intensity and segment control — proprietary SLM stability, 80–240 mm, up to six sources per Hub.", "zh": "风冷固化与预固化（pinning）一体：内置强度与分段控制，专有 SLM 稳定技术，80–240 mm，一个 Hub 管六台。", "vi": "Curing và pinning làm mát bằng khí — điều khiển cường độ và phân đoạn tích hợp, SLM ổn định, 80–240 mm, một Hub quản 6 đèn.", "th": "บ่มและ pinning ระบายความร้อนด้วยอากาศ — ควบคุมความเข้ม/เซกเมนต์ในตัว เทคโนโลยี SLM 80–240 mm หนึ่ง Hub คุมได้ 6 ชุด"}, features: {"en": ["Built-in intensity control: full-cure, low-intensity (pinning), and half-source modes", "Proprietary SLM technology for process stability and repeatable output", "Available lengths: 80, 120, 160, 180, 240 mm", "Air-cooled — no water connections required", "Segment control: disable left or right half for precise UV coverage", "Scalable: stack end-to-end for contiguous uniform UV output", "Hub supports up to six light sources, managed as a single unit"], "zh": ["内置强度控制：完全固化、低强度（预固化(定位固化)）和半光源模式", "专有 SLM 技术，确保工艺稳定性和可重复的输出", "可选长度：80、120、160、180、240 mm", "风冷 — 无需水连接", "分段控制：禁用左半或右半以实现精确的 UV 覆盖", "可扩展：端对端堆叠，实现连续均匀的 UV 输出", "Hub 最多支持六个光源，作为单一单元进行管理"], "vi": ["Điều khiển cường độ tích hợp: chế độ đóng rắn hoàn toàn, cường độ thấp (định vị sơ bộ) và nửa nguồn sáng", "Công nghệ SLM độc quyền để ổn định quy trình và đầu ra lặp lại", "Chiều dài có sẵn: 80, 120, 160, 180, 240 mm", "Làm mát bằng khí — không cần kết nối nước", "Điều khiển phân đoạn: tắt nửa trái hoặc phải để phủ UV chính xác", "Có thể mở rộng: xếp chồng đầu nối đầu để có đầu ra UV liền mạch, đồng đều", "Hub hỗ trợ tối đa sáu nguồn sáng, được quản lý như một đơn vị duy nhất"], "th": ["การควบคุมความเข้มในตัว: โหมดบ่มเต็มรูปแบบ ความเข้มต่ำ (ตรึงหมึก) และครึ่งแหล่งกำเนิดแสง","เทคโนโลยี SLM เพื่อความเสถียรของกระบวนการและเอาต์พุตที่ทำซ้ำได้","ความยาวที่มีให้เลือก: 80, 120, 160, 180, 240 mm","ระบายความร้อนด้วยอากาศ — ไม่ต้องต่อน้ำ","การควบคุมแบบแบ่งส่วน: ปิดครึ่งซ้ายหรือขวาเพื่อการครอบคลุม UV ที่แม่นยำ","ขยายขนาดได้: ต่อเรียงกันเพื่อเอาต์พุต UV ที่สม่ำเสมอต่อเนื่อง","Hub รองรับแหล่งกำเนิดแสงได้สูงสุดหกตัว จัดการเป็นหน่วยเดียว"]} },
  "fj800": { intro: {"en": "Modular large-area curing for low-irradiance, long-dwell applications — scales in all four directions from a 100 × 100 mm base, 365/395 nm.", "zh": "模块化大面积固化：从 100×100 mm 基础单元向四个方向扩展，适合低光强长驻留应用，365/395 nm。", "vi": "Curing diện rộng dạng mô-đun — mở rộng bốn hướng từ nền 100×100 mm, cho ứng dụng cường độ thấp thời gian dài, 365/395 nm.", "th": "บ่มพื้นที่กว้างแบบโมดูลาร์ — ขยายได้สี่ทิศจากฐาน 100×100 mm เหมาะกับงานความเข้มต่ำ dwell นาน 365/395 nm"}, features: {"en": ["Modular and scalable: 100 mm × 100 mm base, scalable in all four directions", "Contiguous, uniform UV output across the entire curing area", "Simple controller supporting up to six light sources", "Available wavelengths: 365, 395 nm", "Air-cooled for flexible, cost-effective integration", "Optimized for large-area curing requiring low irradiance and long dwell time"], "zh": ["模块化且可扩展：100 mm × 100 mm 基础单元，可向四个方向扩展", "在整个固化区域内提供连续、均匀的 UV 输出", "简易控制器，最多支持六个光源", "可选波长：365、395 nm", "风冷设计，实现灵活、经济高效的集成", "针对需要低辐照度和长停留时间的大面积固化进行了优化"], "vi": ["Mô-đun và có thể mở rộng: cơ sở 100 mm × 100 mm, mở rộng theo cả bốn hướng", "Đầu ra UV liền mạch, đồng đều trên toàn bộ vùng đóng rắn", "Bộ điều khiển đơn giản hỗ trợ tối đa sáu nguồn sáng", "Bước sóng có sẵn: 365, 395 nm", "Làm mát bằng khí để tích hợp linh hoạt, hiệu quả về chi phí", "Tối ưu cho đóng rắn diện tích lớn yêu cầu độ rọi thấp và thời gian lưu dài"], "th": ["โมดูลาร์และขยายขนาดได้: พื้นฐาน 100 mm × 100 mm ขยายได้ทั้งสี่ทิศทาง","เอาต์พุต UV ที่ต่อเนื่องและสม่ำเสมอทั่วทั้งพื้นที่บ่ม","ตัวควบคุมที่เรียบง่ายรองรับแหล่งกำเนิดแสงได้สูงสุดหกตัว","ความยาวคลื่นที่มีให้เลือก: 365, 395 nm","ระบายความร้อนด้วยอากาศเพื่อการผสานรวมที่ยืดหยุ่นและคุ้มค่า","ปรับให้เหมาะกับการบ่มพื้นที่ขนาดใหญ่ที่ต้องการความเข้มรังสีต่ำและเวลาคงอยู่นาน"]} },
  "drf-series": { intro: {"en": "The fiber-industry standard for coating and ink curing — proprietary elliptical reflectors focus intense UV through a sealed quartz tube; 1.8–6 kW.", "zh": "光纤行业标准固化系统：专有椭圆反射镜把高强 UV 聚焦到穿过密封石英管的光纤上，功率 1.8–6 kW。", "vi": "Chuẩn ngành sợi quang — gương phản xạ elip độc quyền hội tụ UV cường độ cao qua ống thạch anh kín, 1,8–6 kW.", "th": "มาตรฐานอุตสาหกรรมไฟเบอร์ — รีเฟลกเตอร์วงรีเฉพาะโฟกัส UV เข้มสูงผ่านท่อควอตซ์ซีล กำลัง 1.8–6 kW"}, features: {"en": ["Proprietary secondary elliptical reflector: highest UV irradiance per watt", "Highly focused, intense UV energy for optical fiber curing", "Sealed quartz tube enables full-surface UV exposure with minimal stray radiation", "Noblelight microwave-powered electrodeless lamp: stable, consistent UV output", "Reaches maximum curing power within seconds of ignition", "Modular design for easy maintenance and component replacement", "Interchangeable bulbs to match spectral output to coating needs", "Optional easy-align lamp mounting system", "Optional proprietary back reflector for enhanced UV efficiency", "Individual lamp switching in multi-lamp setups for line-speed adjustment"], "zh": ["专有二次椭圆反射器：每瓦最高 UV 辐照度", "高度聚焦、强烈的 UV 能量，用于光纤固化", "密封石英管实现全表面 UV 曝光，杂散辐射极小", "Noblelight 微波驱动无极灯：稳定、一致的 UV 输出", "点火后数秒内达到最大固化功率", "模块化设计，便于维护和更换组件", "可互换灯泡，使光谱输出与涂层需求相匹配", "可选的易对准灯安装系统", "可选的专有背面反射器，提升 UV 效率", "在多灯配置中可单独切换灯，以调整线速度"], "vi": ["Gương phản xạ elip thứ cấp độc quyền: độ rọi UV cao nhất trên mỗi watt", "Năng lượng UV cường độ cao, hội tụ cao cho đóng rắn sợi quang", "Ống thạch anh kín cho phép phơi UV toàn bề mặt với bức xạ tản lạc tối thiểu", "Đèn không điện cực được cấp nguồn bằng vi sóng Noblelight: đầu ra UV ổn định, đồng nhất", "Đạt công suất đóng rắn tối đa trong vòng vài giây sau khi khởi động", "Thiết kế mô-đun để dễ dàng bảo trì và thay thế linh kiện", "Bóng đèn có thể thay thế lẫn nhau để phù hợp đầu ra quang phổ với nhu cầu lớp phủ", "Hệ thống lắp đèn dễ căn chỉnh tùy chọn", "Gương phản xạ sau độc quyền tùy chọn để nâng cao hiệu suất UV", "Chuyển đổi đèn riêng lẻ trong cấu hình nhiều đèn để điều chỉnh tốc độ dây chuyền"], "th": ["ตัวสะท้อนวงรีทุติยภูมิ: ความเข้มรังสี UV สูงสุดต่อวัตต์","พลังงาน UV ที่โฟกัสสูงและเข้มข้นสำหรับการบ่มเส้นใยแก้วนำแสง","ท่อควอตซ์ปิดผนึกช่วยให้ฉาย UV เต็มพื้นผิวโดยมีรังสีกระเจิงน้อยที่สุด","หลอดไร้ขั้วอิเล็กโทรดขับด้วยไมโครเวฟ Noblelight: เอาต์พุต UV ที่เสถียรและสม่ำเสมอ","ไปถึงกำลังบ่มสูงสุดภายในไม่กี่วินาทีหลังจุดติด","ดีไซน์แบบโมดูลาร์เพื่อการบำรุงรักษาและเปลี่ยนชิ้นส่วนที่ง่าย","หลอดที่เปลี่ยนสลับกันได้เพื่อให้เอาต์พุตสเปกตรัมตรงกับความต้องการของสารเคลือบ","ระบบยึดหลอดที่จัดตำแหน่งง่ายเป็นตัวเลือก","ตัวสะท้อนด้านหลังเป็นตัวเลือกเพื่อเพิ่มประสิทธิภาพ UV","การสลับหลอดแยกเดี่ยวในการติดตั้งหลายหลอดเพื่อปรับความเร็วสายการผลิต"]} },
  "ir-golden8": { intro: {"en": "The twin quartz tube in the shape of an eight, with a gold reflector behind it — double the radiation density and enough mechanical stability for emitters up to 6.5 m long. Supplied short-wave, fast-response medium-wave or medium-wave, so the wavelength is matched to the material rather than the other way round.", "zh": "呈 8 字形的双石英管，背面镀金反射层——辐射密度翻倍，机械强度足以做到 6.5 米长。提供短波、快中波、中波三种波长，是按材料选灯，而不是让材料迁就灯。", "vi": "Ống thạch anh đôi hình số tám với gương vàng phía sau — mật độ bức xạ gấp đôi và đủ bền cơ học cho chiều dài tới 6,5 m. Có bản sóng ngắn, sóng trung phản hồi nhanh và sóng trung, để bước sóng khớp với vật liệu chứ không ngược lại.", "th": "หลอดควอตซ์คู่รูปเลขแปดพร้อมกระจกทองด้านหลัง — ความหนาแน่นการแผ่รังสีเป็นสองเท่า และแข็งแรงพอสำหรับความยาวถึง 6.5 เมตร มีทั้งคลื่นสั้น คลื่นกลางตอบสนองเร็ว และคลื่นกลาง เพื่อให้ความยาวคลื่นเข้ากับวัสดุ ไม่ใช่ให้วัสดุตามหลอด"}, features: {"en": ["High-purity quartz glass for good transmission and thermal stability", "Gold reflector emits the heat directly at the product, almost doubling the effective radiation", "Twin tube (the “Golden 8”) for high radiation density and stability, even at 6.5 m", "Three wavelengths — short-wave, fast-response medium-wave and medium-wave", "Wavelength, dimensions and filament made to the application", "Robust ceramic lamp base"], "zh": ["高纯石英玻璃，透过率好、耐热性稳定", "镀金反射层将热直接投向产品，有效辐射几乎翻倍", "双管结构（Golden 8）辐射密度高、机械稳定，做到 6.5 米仍可靠", "三种波长——短波、快中波、中波", "波长、尺寸与灯丝按应用定制", "坚固的陶瓷灯头"], "vi": ["Thạch anh độ tinh khiết cao, truyền qua tốt và ổn định nhiệt", "Gương vàng hắt nhiệt thẳng vào sản phẩm, gần như nhân đôi bức xạ hữu ích", "Ống đôi (“Golden 8”) cho mật độ bức xạ cao và ổn định cơ học, kể cả ở 6,5 m", "Ba bước sóng — sóng ngắn, sóng trung phản hồi nhanh, sóng trung", "Bước sóng, kích thước và dây tóc làm theo ứng dụng", "Đế đèn gốm chắc chắn"], "th": ["ควอตซ์ความบริสุทธิ์สูง ส่งผ่านแสงดีและทนความร้อนได้ดี", "กระจกทองสะท้อนความร้อนตรงสู่ผลิตภัณฑ์ เพิ่มรังสีที่ใช้ได้เกือบเท่าตัว", "หลอดคู่ (“Golden 8”) ให้ความหนาแน่นรังสีสูงและมั่นคง แม้ที่ความยาว 6.5 เมตร", "สามความยาวคลื่น — คลื่นสั้น คลื่นกลางตอบสนองเร็ว และคลื่นกลาง", "ความยาวคลื่น ขนาด และไส้หลอด ทำตามการใช้งาน", "ขั้วหลอดเซรามิกแข็งแรง"]} },
  "ir-carbon-cir": { intro: {"en": "A carbon heating filament inside the Golden 8 twin tube — medium-wave radiation at high power density, but with a response time in seconds. On water-based coatings it does the same drying job as a short-wave emitter on up to 30% less energy.", "zh": "Golden 8 双管里装的是碳丝——中波辐射、功率密度高，但响应时间只有几秒。烘水性涂料时，能耗比短波灯低三成。", "vi": "Dây tóc carbon bên trong ống đôi Golden 8 — bức xạ sóng trung ở mật độ công suất cao nhưng thời gian phản hồi chỉ vài giây. Với lớp phủ gốc nước, nó sấy như bộ phát sóng ngắn nhưng tốn ít hơn tới 30% năng lượng.", "th": "ไส้หลอดคาร์บอนภายในหลอดคู่ Golden 8 — รังสีคลื่นกลางที่ความหนาแน่นกำลังสูง แต่ตอบสนองภายในไม่กี่วินาที กับสารเคลือบสูตรน้ำ ใช้พลังงานน้อยกว่าตัวเปล่งคลื่นสั้นได้ถึง 30%"}, features: {"en": ["Carbon heating filament — medium-wave radiation with a 1–2 s response time", "Up to 30% less energy than short-wave emitters when drying water-based coatings", "Medium-wave radiation is absorbed particularly well by water, glass and many plastics", "Twin tube (the “Golden 8”) for double power and mechanical stability", "Also available as a round tube", "Gold reflector for directed radiation; robust ceramic lamp base"], "zh": ["碳丝发热——中波辐射，响应时间 1–2 秒", "烘水性涂料比短波灯最多省 30% 能耗", "中波辐射被水、玻璃和多数塑料吸收得特别好", "双管结构（Golden 8），功率翻倍、机械稳定", "也提供单管（圆管）型式", "镀金反射层定向辐射；坚固陶瓷灯头"], "vi": ["Dây tóc carbon — bức xạ sóng trung với thời gian phản hồi 1–2 s", "Tiết kiệm tới 30% năng lượng so với sóng ngắn khi sấy lớp phủ gốc nước", "Bức xạ sóng trung được nước, kính và nhiều loại nhựa hấp thụ rất tốt", "Ống đôi (“Golden 8”) cho công suất gấp đôi và ổn định cơ học", "Cũng có dạng ống tròn", "Gương vàng cho bức xạ định hướng; đế đèn gốm chắc chắn"], "th": ["ไส้หลอดคาร์บอน — รังสีคลื่นกลาง ตอบสนองใน 1–2 วินาที", "ประหยัดพลังงานได้ถึง 30% เทียบกับคลื่นสั้นเมื่ออบสารเคลือบสูตรน้ำ", "รังสีคลื่นกลางถูกดูดกลืนได้ดีมากโดยน้ำ แก้ว และพลาสติกหลายชนิด", "หลอดคู่ (“Golden 8”) ให้กำลังเป็นสองเท่าและมั่นคง", "มีแบบหลอดกลมให้เลือกด้วย", "กระจกทองให้รังสีมีทิศทาง ขั้วหลอดเซรามิกแข็งแรง"]} },
  "ir-round-tube": { intro: {"en": "A single heating filament in a quartz tube. Usually shorter than a twin tube and the right answer when the heated area is small — with a gold or QRC® reflector as required, and as an Infralight® NIR halogen emitter where very high power density is needed.", "zh": "石英管里只有一根灯丝。通常比双管短，加热面积小的时候正合适——可按需配镀金或 QRC® 反射层，需要极高功率密度时还有 Infralight® NIR 卤素型。", "vi": "Một dây tóc duy nhất trong ống thạch anh. Thường ngắn hơn ống đôi và là lựa chọn đúng khi vùng gia nhiệt nhỏ — có gương vàng hoặc QRC® theo yêu cầu, và bản halogen Infralight® NIR khi cần mật độ công suất rất cao.", "th": "ไส้หลอดเดียวในหลอดควอตซ์ มักสั้นกว่าหลอดคู่ และเหมาะเมื่อพื้นที่ให้ความร้อนมีขนาดเล็ก — เลือกกระจกทองหรือ QRC® ได้ตามต้องการ และมีรุ่นฮาโลเจน Infralight® NIR เมื่อต้องการความหนาแน่นกำลังสูงมาก"}, features: {"en": ["One heating filament in high-quality quartz glass", "Shorter than twin-tube emitters in most cases — suits compact heating fields", "Optional gold reflector almost doubles the radiation reaching the product", "QRC® quartz reflector available for aggressive environments and vacuum", "Infralight® NIR halogen version: near-infrared spectrum, very fast response", "Available as carbon or short-wave; can be built into a complete IR system"], "zh": ["高品质石英玻璃内单根灯丝", "多数情况比双管短，适合紧凑加热区", "选配镀金反射层，到达产品的辐射几乎翻倍", "可选 QRC® 石英反射层，适应腐蚀环境与真空", "Infralight® NIR 卤素型：近红外光谱，响应极快", "提供碳丝与短波型；可整合为完整红外系统"], "vi": ["Một dây tóc trong thạch anh chất lượng cao", "Thường ngắn hơn ống đôi — hợp với vùng gia nhiệt gọn", "Gương vàng tùy chọn gần như nhân đôi bức xạ tới sản phẩm", "Có gương thạch anh QRC® cho môi trường ăn mòn và chân không", "Bản halogen Infralight® NIR: phổ cận hồng ngoại, phản hồi rất nhanh", "Có bản carbon và sóng ngắn; tích hợp được thành hệ thống IR hoàn chỉnh"], "th": ["ไส้หลอดเดียวในควอตซ์คุณภาพสูง", "ส่วนใหญ่สั้นกว่าหลอดคู่ — เหมาะกับพื้นที่ให้ความร้อนที่กะทัดรัด", "กระจกทองแบบเลือกได้ เพิ่มรังสีที่ถึงผลิตภัณฑ์เกือบเท่าตัว", "มีกระจกควอตซ์ QRC® สำหรับสภาพกัดกร่อนและสุญญากาศ", "รุ่นฮาโลเจน Infralight® NIR: สเปกตรัมใกล้อินฟราเรด ตอบสนองเร็วมาก", "มีทั้งแบบคาร์บอนและคลื่นสั้น สร้างเป็นระบบ IR ครบชุดได้"]} },
  "ir-contoured": { intro: {"en": "Shaped to the part. The emitter follows the corners, edges and contours of the product so the heat lands only where the process needs it — and nowhere else.", "zh": "按工件形状定做。灯管随产品的角、边和轮廓走，热只落在工艺需要的地方，别处不烤。", "vi": "Tạo hình theo chi tiết. Bộ phát bám theo góc, cạnh và đường bao của sản phẩm, nên nhiệt chỉ rơi đúng nơi quy trình cần.", "th": "ขึ้นรูปตามชิ้นงาน ตัวเปล่งวิ่งตามมุม ขอบ และเส้นขอบของผลิตภัณฑ์ ความร้อนจึงลงเฉพาะจุดที่กระบวนการต้องการ"}, features: {"en": ["Shape, size and spectrum adjusted to the process", "Directed heating of edges, corners, rims and burrs", "High power on a small area", "Switches on and off within seconds", "Saves energy because heat is generated only where it is needed", "Also available as a contoured QRC® emitter"], "zh": ["形状、尺寸与光谱按工艺调整", "定向加热边、角、缘口与毛刺", "小面积上的高功率", "数秒内开关", "只在需要的地方生热，因而省能", "也可做成随形 QRC® 发射器"], "vi": ["Hình dạng, kích thước và phổ điều chỉnh theo quy trình", "Gia nhiệt có hướng vào cạnh, góc, mép và bavia", "Công suất cao trên diện tích nhỏ", "Bật tắt trong vài giây", "Tiết kiệm năng lượng vì chỉ sinh nhiệt nơi cần", "Cũng có bản QRC® tạo hình"], "th": ["รูปทรง ขนาด และสเปกตรัมปรับตามกระบวนการ", "ให้ความร้อนแบบมีทิศทางที่ขอบ มุม ริม และครีบ", "กำลังสูงบนพื้นที่เล็ก", "เปิดปิดได้ภายในไม่กี่วินาที", "ประหยัดพลังงานเพราะสร้างความร้อนเฉพาะจุดที่ต้องการ", "มีรุ่น QRC® ขึ้นรูปตามเส้นขอบด้วย"]} },
  "ir-spotlight": { intro: {"en": "High-intensity heat on a very small area — the emitter for processes where a single point on the part has to reach temperature and the rest must not.", "zh": "把高强度的热打在很小的一块面上——工艺只需要工件上一个点升温、其余部位不能受热时用它。", "vi": "Đưa nhiệt cường độ cao vào một vùng rất nhỏ — dùng khi quy trình chỉ cần một điểm trên chi tiết đạt nhiệt độ còn phần còn lại thì không.", "th": "ส่งความร้อนความเข้มสูงลงบนพื้นที่เล็กมาก — ใช้เมื่อกระบวนการต้องการให้จุดเดียวบนชิ้นงานร้อน ส่วนที่เหลือต้องไม่ร้อน"}, features: {"en": ["Concentrates high intensity on a very small area", "Heat only where the process needs it, with minimal loss to the surroundings", "Switches on and off within seconds", "Shape, size and spectrum adjusted to the process", "Suits automation of short-cycle operations"], "zh": ["把高强度集中在极小面积上", "热只在工艺需要的地方，向环境的散失很小", "数秒内开关", "形状、尺寸与光谱按工艺调整", "适合短节拍工序的自动化"], "vi": ["Tập trung cường độ cao vào vùng rất nhỏ", "Nhiệt chỉ ở nơi quy trình cần, thất thoát ra môi trường rất ít", "Bật tắt trong vài giây", "Hình dạng, kích thước và phổ điều chỉnh theo quy trình", "Hợp cho tự động hóa các nguyên công chu kỳ ngắn"], "th": ["รวมความเข้มสูงไว้บนพื้นที่เล็กมาก", "ความร้อนอยู่เฉพาะที่กระบวนการต้องการ สูญเสียสู่สิ่งแวดล้อมน้อยมาก", "เปิดปิดได้ภายในไม่กี่วินาที", "รูปทรง ขนาด และสเปกตรัมปรับตามกระบวนการ", "เหมาะกับการทำอัตโนมัติในงานรอบสั้น"]} },
  "ir-spiral": { intro: {"en": "A flat spiral of quartz tube, so a round part sees an even field of radiation. Suitable for operation in a vacuum, in short-wave or medium-wave.", "zh": "石英管盘成平面螺旋，圆形工件因此看到一片均匀的辐射。可在真空中工作，提供短波与中波两种。", "vi": "Ống thạch anh cuộn thành xoắn ốc phẳng, nên chi tiết tròn nhận được trường bức xạ đồng đều. Hoạt động được trong chân không, có bản sóng ngắn và sóng trung.", "th": "หลอดควอตซ์ขดเป็นเกลียวแบน ชิ้นงานทรงกลมจึงได้รับสนามรังสีที่สม่ำเสมอ ใช้งานในสุญญากาศได้ มีทั้งคลื่นสั้นและคลื่นกลาง"}, features: {"en": ["Flat spiral shape for homogeneous heating of round parts", "Suitable for operation in a vacuum", "Available with short-wave or medium-wave radiation", "Shape, size and spectrum adjusted to the process", "Switches on and off within seconds"], "zh": ["平面螺旋形，圆形工件受热均匀", "可在真空中运行", "提供短波或中波辐射", "形状、尺寸与光谱按工艺调整", "数秒内开关"], "vi": ["Hình xoắn ốc phẳng cho gia nhiệt đồng đều chi tiết tròn", "Hoạt động được trong chân không", "Có bức xạ sóng ngắn hoặc sóng trung", "Hình dạng, kích thước và phổ điều chỉnh theo quy trình", "Bật tắt trong vài giây"], "th": ["รูปเกลียวแบนให้ความร้อนชิ้นงานทรงกลมอย่างสม่ำเสมอ", "ใช้งานในสุญญากาศได้", "มีทั้งรังสีคลื่นสั้นและคลื่นกลาง", "รูปทรง ขนาด และสเปกตรัมปรับตามกระบวนการ", "เปิดปิดได้ภายในไม่กี่วินาที"]} },
  "ir-small-surface": { intro: {"en": "Twin and quattro emitters that can be arranged along the edges of a three-dimensional part, easy to control and able to put a relatively large amount of energy into a limited area in a short time.", "zh": "双管与四管型式，可以沿三维工件的边缘排布，好控制，能在短时间内把较多能量送进一小片区域。", "vi": "Bản twin và quattro, có thể bố trí dọc theo cạnh của chi tiết ba chiều, dễ điều khiển và đưa được lượng năng lượng tương đối lớn vào vùng hạn chế trong thời gian ngắn.", "th": "แบบ twin และ quattro จัดวางตามขอบของชิ้นงานสามมิติได้ ควบคุมง่าย และส่งพลังงานค่อนข้างมากเข้าสู่พื้นที่จำกัดในเวลาสั้น"}, features: {"en": ["Twin and quattro designs for edges of three-dimensional products", "High energy into a limited area within a short time", "Very well controllable", "Short-wave radiation", "Arrangement adjusted to the part"], "zh": ["双管与四管型式，沿三维工件边缘布置", "短时间内把较多能量送进有限区域", "很好控制", "短波辐射", "排布方式按工件调整"], "vi": ["Thiết kế twin và quattro cho cạnh của chi tiết ba chiều", "Đưa nhiều năng lượng vào vùng hạn chế trong thời gian ngắn", "Rất dễ điều khiển", "Bức xạ sóng ngắn", "Cách bố trí điều chỉnh theo chi tiết"], "th": ["แบบ twin และ quattro สำหรับขอบชิ้นงานสามมิติ", "ส่งพลังงานมากเข้าสู่พื้นที่จำกัดในเวลาสั้น", "ควบคุมได้ดีมาก", "รังสีคลื่นสั้น", "การจัดวางปรับตามชิ้นงาน"]} },
  "ir-omega": { intro: {"en": "A circular short-wave emitter for hot staking — to rivet two parts together it heats the rivet, not the whole part. Heat-up and cool-down in seconds make very short process times possible.", "zh": "环形短波灯，用于热铆——要把两个件铆在一起，它只加热铆点，不烤整件。升温和冷却都以秒计，节拍可以做得很短。", "vi": "Bộ phát sóng ngắn hình vòng cho hot staking — để tán hai chi tiết lại với nhau, nó chỉ nung đinh tán chứ không nung cả chi tiết. Nóng lên và nguội trong vài giây nên chu kỳ rất ngắn.", "th": "ตัวเปล่งคลื่นสั้นทรงวงแหวนสำหรับ hot staking — เพื่อย้ำสองชิ้นเข้าด้วยกัน มันให้ความร้อนเฉพาะหมุดย้ำ ไม่ใช่ทั้งชิ้นงาน ร้อนและเย็นภายในไม่กี่วินาที ทำให้รอบการผลิตสั้นมาก"}, features: {"en": ["Circular short-wave emitter for hot staking", "Heats only the rivet or joint, not the whole part", "Heat-up and cool-down in seconds", "Very short process times", "Ideal for automated joining cells"], "zh": ["环形短波灯，用于热铆", "只加热铆点或接合处，不烤整件", "升温与冷却都以秒计", "工艺节拍很短", "适合自动化接合工位"], "vi": ["Bộ phát sóng ngắn hình vòng cho hot staking", "Chỉ nung đinh tán hoặc mối ghép, không nung cả chi tiết", "Nóng lên và nguội trong vài giây", "Thời gian chu kỳ rất ngắn", "Lý tưởng cho ô tự động hóa ghép nối"], "th": ["ตัวเปล่งคลื่นสั้นทรงวงแหวนสำหรับ hot staking", "ให้ความร้อนเฉพาะหมุดย้ำหรือรอยต่อ ไม่ใช่ทั้งชิ้น", "ร้อนและเย็นภายในไม่กี่วินาที", "รอบการผลิตสั้นมาก", "เหมาะกับสถานีประกอบอัตโนมัติ"]} },
  "ir-slot": { intro: {"en": "A twin tube with a slot cut in one channel, so the emitter itself becomes a drying and heating channel for threads, fibres and ropes. A gold reflector raises the efficiency.", "zh": "双管的其中一管开了一道槽，灯本身就成了一条烘丝、纤维和绳索的加热通道。镀金反射层进一步提高效率。", "vi": "Ống đôi có một rãnh xẻ trên một kênh, nên bản thân bộ phát trở thành kênh sấy và gia nhiệt cho chỉ, sợi và dây. Gương vàng nâng thêm hiệu suất.", "th": "หลอดคู่ที่มีร่องเปิดอยู่ที่ช่องหนึ่ง ตัวเปล่งจึงกลายเป็นช่องอบและให้ความร้อนสำหรับเส้นด้าย เส้นใย และเชือก กระจกทองช่วยเพิ่มประสิทธิภาพ"}, features: {"en": ["Slot in one channel of the twin tube forms a heating channel", "The running material passes through the emitter itself", "Gold reflector increases efficiency", "Compact — no separate oven around the line", "Shape and spectrum adjusted to the process"], "zh": ["双管其中一管开槽，形成加热通道", "走线材料直接穿过灯管本身", "镀金反射层提高效率", "结构紧凑——产线周围不必再建烘箱", "形状与光谱按工艺调整"], "vi": ["Rãnh trên một kênh của ống đôi tạo thành kênh gia nhiệt", "Vật liệu chạy đi thẳng qua chính bộ phát", "Gương vàng nâng hiệu suất", "Gọn — không cần lò riêng bao quanh dây chuyền", "Hình dạng và phổ điều chỉnh theo quy trình"], "th": ["ร่องบนช่องหนึ่งของหลอดคู่กลายเป็นช่องให้ความร้อน", "วัสดุที่วิ่งผ่านลอดผ่านตัวเปล่งโดยตรง", "กระจกทองเพิ่มประสิทธิภาพ", "กะทัดรัด — ไม่ต้องมีเตาอบล้อมรอบสายการผลิต", "รูปทรงและสเปกตรัมปรับตามกระบวนการ"]} },
  "ir-qrc": { intro: {"en": "QRC® — quartz reflective coating. Instead of gold or a metal oxide, the reflector is opaque quartz glass, so it stands up to heat, acid, alkali and corroding substances, and works in a vacuum.", "zh": "QRC®——石英反射涂层。反射层不是金，也不是金属氧化物，而是不透明石英玻璃，因而耐热、耐酸、耐碱、耐腐蚀，也可在真空中使用。", "vi": "QRC® — lớp phủ phản xạ thạch anh. Thay vì vàng hay oxit kim loại, gương là thủy tinh thạch anh mờ, nên chịu được nhiệt, axit, kiềm và chất ăn mòn, và làm việc được trong chân không.", "th": "QRC® — สารเคลือบสะท้อนแสงควอตซ์ กระจกไม่ได้ทำจากทองหรือออกไซด์โลหะ แต่เป็นแก้วควอตซ์ทึบ จึงทนความร้อน กรด ด่าง และสารกัดกร่อน และใช้ในสุญญากาศได้"}, features: {"en": ["Nano-reflector of opaque quartz glass rather than gold or metal oxide", "Extremely resistant to heat, acid, alkaline solutions and corroding substances", "Survives plants that are cleaned regularly with corrosive agents", "Can be bent or formed to the edges and contours of a product", "Nano XP version for applications with high power demands", "Available on twin tube and round tube emitters"], "zh": ["纳米反射层为不透明石英玻璃，而非金或金属氧化物", "极耐热，耐酸、碱与腐蚀性物质", "可用于需定期用腐蚀性清洗剂清洗的车间", "可弯折成形，贴合产品的边与轮廓", "高功率需求另有 Nano XP 型", "双管与单管均可配备"], "vi": ["Gương nano bằng thủy tinh thạch anh mờ thay vì vàng hay oxit kim loại", "Cực kỳ bền với nhiệt, axit, dung dịch kiềm và chất ăn mòn", "Chịu được nhà máy phải vệ sinh thường xuyên bằng chất ăn mòn", "Uốn hoặc tạo hình theo cạnh và đường bao sản phẩm", "Bản Nano XP cho ứng dụng đòi hỏi công suất cao", "Có trên cả ống đôi và ống tròn"], "th": ["กระจกนาโนทำจากแก้วควอตซ์ทึบ แทนที่จะเป็นทองหรือออกไซด์โลหะ", "ทนความร้อน กรด ด่าง และสารกัดกร่อนได้สูงมาก", "ทนโรงงานที่ต้องล้างด้วยสารกัดกร่อนเป็นประจำ", "ดัดหรือขึ้นรูปตามขอบและเส้นขอบของผลิตภัณฑ์ได้", "มีรุ่น Nano XP สำหรับงานที่ต้องการกำลังสูง", "มีให้ทั้งหลอดคู่และหลอดกลม"]} },
  "ir-ip65": { intro: {"en": "A medium-wave emitter with a special-design sealing and the electrical connection routed into a terminal box — dust-tight and splash-proof, so it can heat outdoors and in wet plant.", "zh": "中波发射器，配专门设计的密封结构，电气连接引入接线盒——防尘防溅，因此可以在户外和潮湿车间里加热。", "vi": "Bộ phát sóng trung với kết cấu làm kín thiết kế riêng và đấu điện dẫn vào hộp nối — kín bụi và chống nước bắn, nên có thể gia nhiệt ngoài trời và trong nhà xưởng ẩm ướt.", "th": "ตัวเปล่งคลื่นกลางพร้อมซีลออกแบบพิเศษ และการต่อไฟเดินเข้าสู่กล่องต่อสาย — กันฝุ่นและกันน้ำกระเซ็น จึงให้ความร้อนกลางแจ้งและในโรงงานที่เปียกได้"}, features: {"en": ["IP 65 — sealed against dust and splash water", "Tested by VDE Offenbach over several days; dust-tight and splash-proof", "Electrical connection routed into a terminal box via a special sealing", "Shock-resistant quartz glass, suitable for outdoor use", "Contact-free, well controllable heat transfer", "Medium-wave radiation with extended unheated ends"], "zh": ["IP 65——防尘、防溅水", "经德国 VDE（奥芬巴赫）连续数日测试，确认防尘防溅", "电气连接经专用密封引入接线盒", "抗冲击石英玻璃，适合户外使用", "非接触、易于控制的热传递", "中波辐射，两端为加长非发热段"], "vi": ["IP 65 — kín bụi và chống nước bắn", "Được VDE Offenbach thử nghiệm nhiều ngày; kín bụi và chống nước bắn", "Đấu điện dẫn vào hộp nối qua kết cấu làm kín riêng", "Thạch anh chịu va đập, phù hợp dùng ngoài trời", "Truyền nhiệt không tiếp xúc, dễ điều khiển", "Bức xạ sóng trung với hai đầu không phát nhiệt kéo dài"], "th": ["IP 65 — กันฝุ่นและกันน้ำกระเซ็น", "ผ่านการทดสอบหลายวันโดย VDE Offenbach ยืนยันกันฝุ่นและกันน้ำกระเซ็น", "การต่อไฟเดินเข้าสู่กล่องต่อสายผ่านซีลออกแบบพิเศษ", "ควอตซ์ทนแรงกระแทก เหมาะกับการใช้กลางแจ้ง", "ถ่ายเทความร้อนแบบไม่สัมผัสและควบคุมได้ดี", "รังสีคลื่นกลาง พร้อมปลายทั้งสองด้านที่ไม่ให้ความร้อนแบบยาวพิเศษ"]} },
  "ir-emitter-accessories": { intro: {"en": "An infrared emitter is only as good as what holds it. Every emitter needs a clamping spring and a holding spring so it sits elastically; long emitters need a centre support, and medium-wave emitters last longer on a right-angled safety bracket.", "zh": "红外灯管好不好用，一半取决于怎么装。每支灯都需要一副夹簧和一副压簧，让它有弹性地固定；长灯要在中间加支撑，中波灯装在直角安全支架上寿命更长。", "vi": "Một bộ phát hồng ngoại chỉ tốt bằng thứ giữ nó. Mỗi bộ phát cần một lò xo kẹp và một lò xo giữ để được đỡ đàn hồi; bộ phát dài cần đỡ ở giữa, và bộ phát sóng trung bền hơn khi đặt trên giá an toàn vuông góc.", "th": "ตัวเปล่งอินฟราเรดจะดีได้เท่ากับสิ่งที่ยึดมันไว้ ตัวเปล่งทุกตัวต้องมีสปริงหนีบและสปริงยึดเพื่อให้จับอย่างยืดหยุ่น ตัวเปล่งยาวต้องมีจุดรองรับตรงกลาง และตัวเปล่งคลื่นกลางจะอายุยาวขึ้นเมื่ออยู่บนขายึดนิรภัยมุมฉาก"}, features: {"en": ["Mounting clamps and spring supports make installation straightforward", "Every emitter needs a clamping spring and a holding spring to be held elastically", "Long emitters should be supported in the middle", "Medium-wave emitters last longer when supported by a right-angled safety bracket", "Wire gratings and safety plates in quartz glass and glass ceramics protect emitter and product", "Extraction strips and air-knife modules for optimal air flow", "Wavelength converter raises the energy yield on very thin or transparent products"], "zh": ["安装夹与弹簧支撑，装配简便", "每支灯都要配夹簧与压簧，才能有弹性地固定", "长灯应在中部加支撑", "中波灯配直角安全支架，寿命更长", "石英玻璃与微晶玻璃的护网和安全板，保护灯管与产品", "抽风条与风刀模块，保证气流", "波长转换器可提高极薄或透明产品的能量利用率"], "vi": ["Kẹp lắp và lò xo đỡ giúp lắp đặt dễ dàng", "Mỗi bộ phát cần lò xo kẹp và lò xo giữ để được đỡ đàn hồi", "Bộ phát dài nên được đỡ ở giữa", "Bộ phát sóng trung bền hơn khi có giá an toàn vuông góc", "Lưới và tấm an toàn bằng thạch anh và gốm thủy tinh bảo vệ bộ phát lẫn sản phẩm", "Thanh hút và mô-đun dao khí cho luồng khí tối ưu", "Bộ chuyển bước sóng nâng hiệu suất năng lượng với sản phẩm mỏng hoặc trong suốt"], "th": ["แคลมป์ยึดและสปริงรองรับ ทำให้ติดตั้งง่าย", "ตัวเปล่งทุกตัวต้องมีสปริงหนีบและสปริงยึดเพื่อให้จับอย่างยืดหยุ่น", "ตัวเปล่งที่ยาวควรมีจุดรองรับตรงกลาง", "ตัวเปล่งคลื่นกลางอายุยาวขึ้นเมื่อมีขายึดนิรภัยมุมฉาก", "ตะแกรงลวดและแผ่นนิรภัยจากควอตซ์และแก้วเซรามิกปกป้องทั้งตัวเปล่งและผลิตภัณฑ์", "แถบดูดอากาศและโมดูล air knife เพื่อการไหลของอากาศที่เหมาะสม", "ตัวแปลงความยาวคลื่นเพิ่มผลได้พลังงานกับผลิตภัณฑ์บางหรือโปร่งใส"]} },
  "s-liquid-light-guide": { intro: {"en": "The standard way to get an S Series lamp's output to the joint: a liquid-filled guide in 3, 5 and 8 mm tip diameters and standard lengths from 750 to 3000 mm. Dual and triple-leg versions split one lamp across several cure sites.", "zh": "把 S 系列灯的能量送到胶点的标准做法：液芯导光管，管口 3、5、8 mm 三种，标准长度 750–3000 mm。双分支与三分支型式可把一台灯分到多个固化点。", "vi": "Cách chuẩn để đưa năng lượng của đèn S Series tới mối dán: ống dẫn sáng lõi lỏng, đầu 3, 5 và 8 mm, chiều dài tiêu chuẩn 750–3000 mm. Bản hai và ba nhánh chia một đèn cho nhiều điểm đóng rắn.", "th": "วิธีมาตรฐานในการนำพลังงานจากหลอด S Series ไปยังจุดยึด: ท่อนำแสงแบบไส้ของเหลว ปลายขนาด 3, 5 และ 8 มม. ความยาวมาตรฐาน 750–3000 มม. รุ่นสองและสามขาแยกหลอดเดียวไปยังหลายจุดบ่ม"}, features: {"en": ["Tip diameters of 3, 5 and 8 mm", "Standard lengths from 750 to 3000 mm", "Dual and triple-leg configurations for multi-site curing", "Liquid-filled core rather than bundled fibre", "Fits the OmniCure S1500 Pro and S2000 Elite"], "zh": ["管口直径 3、5、8 mm", "标准长度 750–3000 mm", "提供双分支与三分支，可多点同时固化", "液芯结构，非光纤束", "适配 OmniCure S1500 Pro 与 S2000 Elite"], "vi": ["Đường kính đầu 3, 5 và 8 mm", "Chiều dài tiêu chuẩn 750–3000 mm", "Cấu hình hai và ba nhánh cho đóng rắn nhiều điểm", "Lõi lỏng thay vì bó sợi quang", "Lắp cho OmniCure S1500 Pro và S2000 Elite"], "th": ["เส้นผ่านศูนย์กลางปลาย 3, 5 และ 8 มม.", "ความยาวมาตรฐาน 750–3000 มม.", "มีแบบสองขาและสามขาสำหรับบ่มหลายจุด", "ไส้ของเหลว ไม่ใช่มัดเส้นใยแก้ว", "ใช้กับ OmniCure S1500 Pro และ S2000 Elite"]} },
  "s-fiber-light-guide": { intro: {"en": "A fibre guide that splits one lamp's output evenly across several cure sites — the same energy at every leg, rather than the brightest at the shortest.", "zh": "把一台灯的能量均匀分到多个固化点的光纤导光管——每一路能量相同，而不是短的那路最亮。", "vi": "Ống dẫn sáng sợi quang chia đều năng lượng của một đèn cho nhiều điểm đóng rắn — mọi nhánh nhận cùng năng lượng, không phải nhánh ngắn nhất sáng nhất.", "th": "ท่อนำแสงเส้นใยแก้วที่แบ่งพลังงานจากหลอดเดียวอย่างเท่ากันไปยังหลายจุดบ่ม — ทุกขาได้พลังงานเท่ากัน ไม่ใช่ขาที่สั้นที่สุดสว่างที่สุด"}, features: {"en": ["Equal distribution of light energy to multiple cure sites", "Driven from a single light source", "Fibre construction for high-power duty", "Fits the OmniCure S1500 Pro and S2000 Elite"], "zh": ["多个固化点获得相同的光能", "由单一光源驱动", "光纤结构，适配高功率", "适配 OmniCure S1500 Pro 与 S2000 Elite"], "vi": ["Phân bố năng lượng đều tới nhiều điểm đóng rắn", "Chạy từ một nguồn sáng duy nhất", "Cấu tạo sợi quang cho công suất cao", "Lắp cho OmniCure S1500 Pro và S2000 Elite"], "th": ["กระจายพลังงานแสงเท่ากันไปยังหลายจุดบ่ม", "ขับจากแหล่งกำเนิดแสงเดียว", "โครงสร้างเส้นใยแก้วสำหรับงานกำลังสูง", "ใช้กับ OmniCure S1500 Pro และ S2000 Elite"]} },
  "s-fiber-light-line": { intro: {"en": "A high-output linear beam. The fibres run unbroken from the guide input to the termination, so the coupling losses of a bolted-on light-line accessory do not arise.", "zh": "高输出线形光束。光纤从导光管入口一直连到出光端，中间不断开，因此没有外挂式线光源那种耦合损失。", "vi": "Chùm sáng dạng vạch công suất cao. Sợi quang chạy liền từ đầu vào tới đầu ra nên không có tổn hao ghép nối như phụ kiện light-line lắp ngoài.", "th": "ลำแสงเส้นตรงกำลังสูง เส้นใยแก้ววิ่งต่อเนื่องจากปากทางเข้าจนถึงปลายทางออก จึงไม่มีการสูญเสียจากการต่อประกบแบบอุปกรณ์ light-line ทั่วไป"}, features: {"en": ["High-output linear beam of curing energy", "Fibres continuous from light guide input to termination", "Eliminates the coupling losses of standard light-line accessories", "Fits the OmniCure S1500 Pro and S2000 Elite"], "zh": ["高输出的线形固化光束", "光纤从入口到出光端连续不断", "消除普通线光源附件的耦合损失", "适配 OmniCure S1500 Pro 与 S2000 Elite"], "vi": ["Chùm đóng rắn dạng vạch công suất cao", "Sợi quang liền mạch từ đầu vào tới đầu kết thúc", "Loại bỏ tổn hao ghép nối của phụ kiện light-line thông thường", "Lắp cho OmniCure S1500 Pro và S2000 Elite"], "th": ["ลำแสงบ่มเป็นเส้นตรงกำลังสูง", "เส้นใยแก้วต่อเนื่องจากทางเข้าถึงปลายทางออก", "ตัดการสูญเสียจากการต่อประกบของอุปกรณ์ light-line ทั่วไป", "ใช้กับ OmniCure S1500 Pro และ S2000 Elite"]} },
  "s-cure-ring-adapter": { intro: {"en": "Turns a light guide into a ring: the part passes through the middle and is cured from all sides at once. The standard ring for Liquid Light Guides, in solid or slotted form.", "zh": "把导光管变成一个环：工件从中间穿过，四周同时固化。配液芯导光管使用的标准环，提供整体式与开槽式两种。", "vi": "Biến ống dẫn sáng thành một vòng: chi tiết đi qua giữa và được đóng rắn từ mọi phía cùng lúc. Vòng tiêu chuẩn dùng với ống dẫn sáng lõi lỏng, có bản liền và bản xẻ rãnh.", "th": "เปลี่ยนท่อนำแสงให้เป็นวงแหวน: ชิ้นงานลอดผ่านตรงกลางและถูกบ่มรอบด้านพร้อมกัน เป็นวงแหวนมาตรฐานสำหรับใช้กับท่อนำแสงไส้ของเหลว มีทั้งแบบตันและแบบผ่าร่อง"}, features: {"en": ["Gives a light guide 360° of curing power", "Standard ring for use with Liquid Light Guides", "Available in solid or slotted versions", "Slotted version lets a continuous part be loaded from the side"], "zh": ["让导光管获得 360° 的固化能力", "配液芯导光管使用的标准环", "提供整体式与开槽式两种", "开槽式可让连续料从侧面放入"], "vi": ["Cho ống dẫn sáng khả năng đóng rắn 360°", "Vòng tiêu chuẩn dùng với ống dẫn sáng lõi lỏng", "Có bản liền hoặc bản xẻ rãnh", "Bản xẻ rãnh cho phép nạp vật liệu chạy liên tục từ bên hông"], "th": ["ให้ท่อนำแสงบ่มได้รอบ 360°", "วงแหวนมาตรฐานสำหรับท่อนำแสงไส้ของเหลว", "มีทั้งแบบตันและแบบผ่าร่อง", "แบบผ่าร่องใส่วัสดุที่วิ่งต่อเนื่องจากด้านข้างได้"]} },
  "s-light-line-adapter": { intro: {"en": "Focuses the beam into a line rather than a spot, for a short row of parts — components, tubing or cable up to two inches of line length.", "zh": "把光束聚成一条线而不是一个点，适合短排工件——元件、管材或线缆，线长在两英寸以内。", "vi": "Hội tụ chùm sáng thành một vạch thay vì một điểm, cho hàng chi tiết ngắn — linh kiện, ống hoặc cáp với chiều dài vạch tới hai inch.", "th": "รวมลำแสงให้เป็นเส้นแทนที่จะเป็นจุด สำหรับชิ้นงานเรียงแถวสั้น ๆ — ชิ้นส่วน ท่อ หรือสายเคเบิล ที่ความยาวเส้นไม่เกินสองนิ้ว"}, features: {"en": ["Focused, linear beam of curing energy", "Cures small rows of components, tubing and cables", "Suits anything requiring up to two inches of line length", "Fits the OmniCure S1500 Pro and S2000 Elite"], "zh": ["聚焦的线形固化光束", "固化小排元件、管材与线缆", "适合线长在两英寸以内的场合", "适配 OmniCure S1500 Pro 与 S2000 Elite"], "vi": ["Chùm đóng rắn dạng vạch hội tụ", "Đóng rắn hàng ngắn linh kiện, ống và cáp", "Phù hợp khi cần chiều dài vạch tới hai inch", "Lắp cho OmniCure S1500 Pro và S2000 Elite"], "th": ["ลำแสงบ่มเป็นเส้นแบบโฟกัส", "บ่มชิ้นส่วน ท่อ และสายเคเบิลที่เรียงเป็นแถวสั้น", "เหมาะกับงานที่ต้องการความยาวเส้นไม่เกินสองนิ้ว", "ใช้กับ OmniCure S1500 Pro และ S2000 Elite"]} },
  "s-collimating-adapter": { intro: {"en": "Opens the spot out to a uniform circle anywhere from 1\" to 6\" (2.54 to 15.2 cm), with the power spread evenly across it rather than piled into the centre.", "zh": "把光斑放大成均匀的圆形，直径可在 1–6 英寸（2.54–15.2 cm）之间调节，能量在整个光斑上均匀铺开，而不是全堆在中心。", "vi": "Mở điểm sáng thành một vòng tròn đều, đường kính điều chỉnh từ 1 đến 6 inch (2,54–15,2 cm), năng lượng trải đều thay vì dồn vào giữa.", "th": "ขยายจุดแสงให้เป็นวงกลมสม่ำเสมอ ปรับได้ตั้งแต่ 1 ถึง 6 นิ้ว (2.54–15.2 ซม.) โดยพลังงานกระจายทั่วทั้งวง ไม่กระจุกอยู่ตรงกลาง"}, features: {"en": ["Uniform spot adjustable from 1\" up to 6\" (2.54 cm to 15.2 cm)", "Equal power distribution across the spot for even curing", "One adapter covers the whole range", "Fits the OmniCure S1500 Pro and S2000 Elite"], "zh": ["均匀光斑，1 至 6 英寸（2.54–15.2 cm）可调", "光斑内能量分布均匀，固化更一致", "一只转接头覆盖整个范围", "适配 OmniCure S1500 Pro 与 S2000 Elite"], "vi": ["Điểm sáng đều, điều chỉnh từ 1 tới 6 inch (2,54–15,2 cm)", "Năng lượng phân bố đều trên điểm sáng cho đóng rắn đồng nhất", "Một bộ chuyển bao trọn dải", "Lắp cho OmniCure S1500 Pro và S2000 Elite"], "th": ["จุดแสงสม่ำเสมอ ปรับได้ตั้งแต่ 1 ถึง 6 นิ้ว (2.54–15.2 ซม.)", "พลังงานกระจายเท่ากันทั่วจุดแสง ทำให้บ่มสม่ำเสมอ", "อะแดปเตอร์ตัวเดียวครอบคลุมทั้งช่วง", "ใช้กับ OmniCure S1500 Pro และ S2000 Elite"]} },
};

